-- US admission requirements, wave 2 (schools 137 to 272 by program count), official pages, checked 13 Nov 2026. Needs step181.
update schools set admission_info = $q${"ug": "Admission is highly selective in all majors. International students must meet country based entry requirements and English exam rules. Transcripts for international applicants are reviewed on a separate page.", "pg": "Graduate applicants with a degree from a regionally accredited US school get an automatic English waiver. International graduate applications are handled on a separate page.", "english": "TOEFL iBT 80 (taken before 21 Jan 2026) or 4.5 (on or after that date), IELTS 6.5, Duolingo 115. Scores must be within 2 years. Applicants educated for at least 3 years in English may request a waiver with official transcripts.", "how_to_apply": "Apply for the fall term through Cal State Apply, using the international first-year application. Cal Poly is highly selective.", "deadlines": "First-year application window is 1 October to 30 November. Transcripts and English exam results must arrive by 15 February (31 January for Art and Design or Music).", "application_fee": "$70 per campus, paid with the application.", "documents": "Transcripts, current class schedule, test scores, household annual income, official English exam scores. Official transcripts are needed for any English waiver request.", "fees_link": "https://www.calpoly.edu/admissions/international-student/how-to-apply/application-for-international-first-year-students", "sources": ["https://www.calpoly.edu/admissions/international-student/selection-criteria", "https://www.calpoly.edu/admissions/international-student/selection-criteria/english-exam-requirements", "https://www.calpoly.edu/admissions/international-student/how-to-apply/application-for-international-first-year-students"]}$q$::jsonb, admission_link = $q$https://www.calpoly.edu/admissions/international-student/how-to-apply/application-for-international-first-year-students$q$, admission_checked = '2026-11-13' where id = 'be9aa186-1f16-4bba-b18b-fdcd871b1ec6' and country = 'United States';
update schools set admission_info = $q${"ug": "Secondary school graduation with strong grades. WAEC results are required for West African applicants before a decision.", "pg": "Bachelor's degree with official transcripts and diplomas. Some programs need GRE (code 1258) and a personal statement. Minimum funds for one year are $28,810 after admission.", "english": "Undergraduate: TOEFL iBT 80, IELTS 6.5, Duolingo 105, PTE 53, Cambridge 180, SAT EBRW 470, ACT English 15, or other listed tests. Graduate: TOEFL 80, IELTS 6.5, PTE 53, Duolingo 105.", "how_to_apply": "Apply through the Common Application or the GVSU student portal, then send scores and transcripts directly from the sources. Decisions come about 3 weeks after the file is complete.", "deadlines": "Undergraduate fall: 1 June (financial form 1 July). Winter: 1 November (financial form 15 November). Graduate from outside the US: fall 1 May, winter 15 October.", "application_fee": "Undergraduate: no fee. Graduate: $30.", "documents": "Application, official English scores, official transcripts sent directly by the school, WAEC results for West African applicants, financial verification for the I-20.", "fees_link": "https://www.gvsu.edu/admissions/international-tuition-fees-23", "sources": ["https://www.gvsu.edu/admissions/international-undergraduate-admissions-requirements-37.htm", "https://gvsu.edu/admissions/international-graduate-admissions-requirements-38.htm", "https://www.gvsu.edu/admissions/international-scholarships-and-assistantships-74.htm"]}$q$::jsonb, admission_link = $q$https://www.gvsu.edu/admissions/international-tuition-fees-23$q$, admission_checked = '2026-11-13' where id = '86674afb-c403-4889-8193-01f5cef62831' and country = 'United States';
update schools set admission_info = $q${"ug": "Completion of secondary school (usually 12 years). Units in maths, natural science, history or social science, and English or a foreign language. Some programs need SAT or ACT.", "pg": "Bachelor's degree from an accredited US school or an equivalent foreign degree, with official records. VCU generally does not give financial support to international graduate students.", "english": "Undergraduate: TOEFL iBT 70 (before 21 Jan 2026) or 4.0 (after), IELTS 6.0, PTE 53, Duolingo 105, SAT Reading and Writing 500, ACT English 16. Graduate: TOEFL 80, IELTS 6.5, PTE 65, Duolingo 110. Scores are valid 2 years.", "how_to_apply": "First-year students apply through the Common Application and transfers through the VCU online application. Apply to only one program per term.", "deadlines": "International first-year applicants who apply by 1 November are considered for first-year scholarships. Graduate: fall 1 April, spring 1 October, summer 1 February.", "application_fee": "$75 undergraduate, non-refundable.", "documents": "Passport or visa copy, original or certified academic records with official English translation (not notarized copies), test scores mailed to VCU. Graduate applicants also show financial support.", "fees_link": "https://admissions.vcu.edu/cost-aid/scholarships-funding/first-year-scholarships/", "sources": ["https://admissions.vcu.edu/apply-to-vcu/international/undergraduate", "https://bulletin.vcu.edu/graduate/study/admission-graduate-study/international-students/international-students.pdf", "https://admissions.vcu.edu/cost-aid/scholarships-funding/first-year-scholarships/"]}$q$::jsonb, admission_link = $q$https://admissions.vcu.edu/cost-aid/scholarships-funding/first-year-scholarships/$q$, admission_checked = '2026-11-13' where id = '9364a2fb-677b-42c1-8e54-a6c264562359' and country = 'United States';
update schools set admission_info = $q${"ug": "Minimum GPA 2.5 for freshmen and 2.0 for transfers with 24 or more credits. Official academic records with English translation and proof of funds for the I-20.", "pg": "Bachelor's degree from an accredited school with official transcripts and certified English translation. GRE or GMAT only if the program asks. Proof of funds for the I-20.", "english": "Undergraduate: TOEFL iBT 71, IELTS 6.0, Duolingo 100, PTE 52, SAT EBRW 460. Graduate: TOEFL iBT 79, IELTS 6.5 (Duolingo is not listed).", "how_to_apply": "Submit the WKU application with fee, academic records, English proof and bank statement showing one year of funds. All documents must be in before a decision.", "deadlines": "Application and documents must arrive by 14 December to be processed before the winter break. Other term dates are on the page.", "application_fee": "$75 undergraduate and $95 graduate, non-refundable.", "documents": "Official records with certified translation, English proof, bank statement for one year (affidavit of support if not in your name).", "fees_link": "https://www.wku.edu/international/intlreq.php", "sources": ["https://www.wku.edu/international/intlreq.php", "https://www.wku.edu/international/international-scholarships.php", "https://www.wku.edu/international/issa.php"]}$q$::jsonb, admission_link = $q$https://www.wku.edu/international/intlreq.php$q$, admission_checked = '2026-11-13' where id = 'd61ea818-a14b-4e2f-b135-17b42ebc54a7' and country = 'United States';
update schools set admission_info = $q${"ug": "Secondary school completion. Foreign transcripts need a course-by-course evaluation from a NACES member agency. Passport photo page required.", "english": "TOEFL iBT 71 (before 21 Jan 2026) or 4.0 (after), IELTS 6.0, Duolingo 100, secondary school taught in English with an official school letter, or completion of the EWU English Language Institute.", "how_to_apply": "Apply online with fee and documents. The file is not reviewed until all documents arrive. Graduate requirements are on the EWU International Graduate page.", "deadlines": "For students outside the US needing F-1: winter 21 September, spring 14 December, fall 1 June (recommended dates).", "application_fee": "$65.", "documents": "Online application, NACES transcript evaluation, English proof, passport photo page.", "fees_link": "https://www.ewu.edu/apply/international-student-application/", "sources": ["https://www.ewu.edu/apply/international-student-application/"]}$q$::jsonb, admission_link = $q$https://www.ewu.edu/apply/international-student-application/$q$, admission_checked = '2026-11-13' where id = '474e478e-2892-4168-bc13-5f67fc963e4f' and country = 'United States';
update schools set admission_info = $q${"ug": "Requirements vary by program. Applicants need a course-by-course credential evaluation from a NACES member. Official ACT or SAT scores are needed for merit scholarship consideration.", "pg": "Requirements vary by program and are listed on the Marshall international admissions page.", "english": "All applicants must show proof of English proficiency. Official ACT or SAT scores can also satisfy this. The page does not give minimum scores.", "how_to_apply": "Send the application, fee and official credentials. Undergraduate decisions take about 2 to 3 business days after all documents arrive and graduate decisions about 2 weeks. The page lists no international scholarships.", "deadlines": "Fall 15 June, spring 15 October, summer 15 March.", "application_fee": "$150 for undergraduate and graduate (no waiver). Transfer students also pay a $50 evaluation fee.", "documents": "Official credentials sent directly by the school, NACES course-by-course evaluation, certified English translation for non-English records.", "fees_link": "https://www.marshall.edu/iss/future-students/financial-information/", "sources": ["https://www.marshall.edu/iss/frequently-asked-questions/international-admission-faqs/"]}$q$::jsonb, admission_link = $q$https://www.marshall.edu/iss/future-students/financial-information/$q$, admission_checked = '2026-11-13' where id = '4ffd7753-27e1-4766-b0cc-bea69c453bb3' and country = 'United States';
update schools set admission_info = $q${"ug": "Unweighted GPA of 3.1 or higher is needed for the scholarships. Transcripts must be legible and in English or with a certified translation. Official transcripts are due before the second semester.", "pg": "Bachelor's degree before enrolling. Many programs also ask for GRE, recommendation letters or a statement of purpose.", "english": "Undergraduate: IELTS 6.0, TOEFL iBT 68 (before 26 Jan 2026) or 4 (after), ACT English 18, SAT EBRW 450, Duolingo 100, PTE 50. Graduate: TOEFL 80, IELTS 6.5, Duolingo 115 (higher for some programs).", "how_to_apply": "Apply online with fee, transcripts, English proof and passport copy. Decisions usually come within two weeks of a complete undergraduate application. Applicants below English minimums may be considered for the Pathway Program.", "deadlines": "Undergraduate fall: scholarship deadline 15 December and priority 1 April. Spring: 1 October. Graduate funding deadlines are 15 February (fall) and 1 October (spring).", "application_fee": "$85 undergraduate and $95 graduate, no waiver for international applicants.", "documents": "Transcripts or marksheets, English proof, passport name page. Official transcripts sent in sealed envelope or secure service.", "fees_link": "https://www.boisestate.edu/global-international/cost-and-scholarships/undergraduate-scholarships/", "sources": ["https://www.boisestate.edu/global-international/apply/ia-international-first-year-admission/", "https://www.boisestate.edu/global-international/apply/ia-international-graduate-admission/", "https://www.boisestate.edu/global-international/cost-and-scholarships/undergraduate-scholarships/"]}$q$::jsonb, admission_link = $q$https://www.boisestate.edu/global-international/cost-and-scholarships/undergraduate-scholarships/$q$, admission_checked = '2026-11-13' where id = '186a42c5-3069-4991-aafa-49206f0e112d' and country = 'United States';
update schools set admission_info = $q${"ug": "Official transcripts for the last three years of school. SAT or ACT is optional. F-1 or J-1 applicants send a financial statement and bank statements before the I-20.", "english": "At least one score under 2 years old: TOEFL (mid-range 80 to 95 or 4.0 to 5.0), IELTS (6.5 to 7.0), Duolingo (110 to 120), PTE, Cambridge, SAT or ACT. These are typical ranges, not fixed minimums. A waiver can be requested after 4 years in English-taught school.", "how_to_apply": "Apply through the Common App, SUNY or Coalition application. The page does not say which scholarships are open to international students.", "deadlines": "Early action 1 November (decision 15 January). Regular 15 March (decision by 1 April).", "application_fee": "$50, no fee waiver for international students.", "documents": "Transcripts, translations if needed, English scores, International Student Financial Statement, bank statements.", "fees_link": "https://www.binghamton.edu/admissions/undergraduate/cost/scholarships.html", "sources": ["https://www.binghamton.edu/admissions/undergraduate/apply/international/first-year.html", "https://www.binghamton.edu/admissions/undergraduate/cost/scholarships.html"]}$q$::jsonb, admission_link = $q$https://www.binghamton.edu/admissions/undergraduate/cost/scholarships.html$q$, admission_checked = '2026-11-13' where id = 'b982e118-0cf2-42cc-af97-3346073bc1ba' and country = 'United States';
update schools set admission_info = $q${"ug": "International freshmen who attended a US high school need a 2.5 GPA. Transfers need a 2.0 to 2.5 GPA depending on credit hours. Official transcripts with certified translations.", "english": "TOEFL iBT 69, IELTS 6.0, Duolingo 100, ACT Verbal 27, SAT Verbal 600, or CXC/CSEC English grade 4. Waivers may apply if English was the language of instruction or the home country is on the SHSU list.", "how_to_apply": "Apply through ApplyTexas or Common App. SHSU suggests applying 90 days early. After admission SHSU issues an I-20. The page lists no scholarships for international students.", "deadlines": "Fall 1 August, spring 15 December, summer 15 May. Some graduate programs are earlier.", "application_fee": "$90.", "documents": "Official transcripts, certified translations, passport, immunization records, one year of financial proof, health insurance proof.", "fees_link": "https://www.shsu.edu/admissions/apply/international-steps-checklist", "sources": ["https://www.shsu.edu/admissions/apply/international-steps-checklist"]}$q$::jsonb, admission_link = $q$https://www.shsu.edu/admissions/apply/international-steps-checklist$q$, admission_checked = '2026-11-13' where id = '6c0bbcbf-eca8-42cf-9b18-0392ce21f05b' and country = 'United States';
update schools set admission_info = $q${"ug": "Transcripts, English score, passport copy and proof of financial support. Applicants who meet academic but not English minimums can apply for conditional admission.", "pg": "Transcripts, English score and recommender details. Conditional admission is available for English.", "english": "The pages checked do not give score minimums. TOEFL or IELTS scores are needed for the tuition waiver.", "how_to_apply": "Create an account and apply online. Your admission application also serves as the tuition waiver application.", "deadlines": "Undergraduate: fall 1 June, spring 1 November. Graduate: fall 1 June, spring 1 October, summer 15 February.", "application_fee": "$50 undergraduate. Graduate fee amount not listed.", "documents": "Transcripts, English score, passport copy, proof of financial support.", "fees_link": "https://www.isu.edu/scholarships/apply-for-scholarships/new-incoming-international-students/", "sources": ["https://www.isu.edu/apply/international/", "https://www.isu.edu/scholarships/apply-for-scholarships/new-incoming-international-students/"]}$q$::jsonb, admission_link = $q$https://www.isu.edu/scholarships/apply-for-scholarships/new-incoming-international-students/$q$, admission_checked = '2026-11-13' where id = 'f466eb7e-b287-4cff-a2ba-c9bbbc4b2ea3' and country = 'United States';
update schools set admission_info = $q${"ug": "Secondary transcripts with exam results (such as 10th and 12th grade, CAPE, IGCSE), personal statement, and one recommendation letter encouraged. SAT or ACT is optional.", "pg": "Transcripts, NACES evaluation (limited free evaluation from Montclair), usually two recommendation letters and program items. GRE or GMAT not needed for many programs.", "english": "Undergraduate: TOEFL iBT 70 or 4.0, IELTS 6.0, Duolingo 95, PTE 48. Graduate: TOEFL 83 or 4.5, IELTS 6.5, Duolingo 105, PTE 53. Waivers apply for listed countries.", "how_to_apply": "Apply online. Early applicants have better scholarship chances. The I-20 is issued 5 to 10 business days after a complete application.", "deadlines": "Fall 2027: early action 1 December 2026, scholarship consideration 1 March 2027, final 1 June 2027. Graduate from outside US: fall 1 June, spring 1 November.", "application_fee": "$65 undergraduate and $60 graduate.", "documents": "Transcripts, English scores, essay, recommendation, resume (some majors).", "fees_link": "https://www.montclair.edu/admissions-aid/financial-aid/international-scholarships-and-aid", "sources": ["https://www.montclair.edu/admissions-aid/how-apply-montclair-state-university/international-applicants/international-first-year-applicants", "https://www.montclair.edu/admissions-aid/how-apply-montclair-state-university/international-applicants/international-graduate-applicants", "https://www.montclair.edu/admissions-aid/financial-aid/international-scholarships-and-aid"]}$q$::jsonb, admission_link = $q$https://www.montclair.edu/admissions-aid/financial-aid/international-scholarships-and-aid$q$, admission_checked = '2026-11-13' where id = 'f5492cae-31cf-435d-93bd-32f1896d67b2' and country = 'United States';
update schools set admission_info = $q${"ug": "High school or prior college transcripts with certified translations. SAT or ACT optional. Fake documents lead to denial.", "pg": "Minimum GPA 3.0, and GRE depends on the department.", "english": "Accepted proof is listed on the English proficiency page. Score minimums were not on the pages checked.", "how_to_apply": "Apply online or on paper, pay the fee and send documents to the Office of International Programs.", "deadlines": "Undergraduate: fall 1 July, spring 15 November, summer 15 March. Graduate: fall 15 May, spring 1 October, summer 1 February.", "application_fee": "Undergraduate $38 online or $30 paper. Graduate $60. Not waived.", "documents": "Application, fee, English proof, transcripts (official before registering).", "fees_link": "https://www.montana.edu/international/admissions/INTL_UG_Scholarships.html", "sources": ["https://www.montana.edu/international/admissions/appinstructions.html", "https://www.montana.edu/international/admissions/quickfacts.html", "https://www.montana.edu/international/admissions/INTL_UG_Scholarships.html"]}$q$::jsonb, admission_link = $q$https://www.montana.edu/international/admissions/INTL_UG_Scholarships.html$q$, admission_checked = '2026-11-13' where id = '9f0d50a3-5dc9-4b94-90e6-908e95da9bbb' and country = 'United States';
update schools set admission_info = $q${"ug": "First-year: 3.4 GPA in a-g style courses with C or better in each, so check country requirements. SAT and ACT are not considered for admission. Transfers need 60 semester units and a 2.8 GPA.", "english": "IELTS 6.5, TOEFL iBT 80 (before 2026) or 4.5 (from 2026), Duolingo 115, ACT English 24, AP English 3 or higher, or a US college English composition course with C or better.", "how_to_apply": "Apply on the UC application. UCR may ask for scores above the minimum.", "deadlines": "UC application is open 1 October to 30 November for fall.", "application_fee": "$80 per campus.", "documents": "UC application, test scores and payment. TOEFL or IELTS reports sent to UCR (code 004839).", "fees_link": "https://admissions.ucr.edu/affordable-international", "sources": ["https://admissions.ucr.edu/international", "https://admissions.ucr.edu/affordable-international"]}$q$::jsonb, admission_link = $q$https://admissions.ucr.edu/affordable-international$q$, admission_checked = '2026-11-13' where id = 'ade491be-a86e-4352-87bd-f7d5b1c77e6c' and country = 'United States';
update schools set admission_info = $q${"ug": "Transcripts from every secondary school attended with certified English translation. SAT or ACT not required. Some majors have extra requirements after admission.", "pg": "Transcripts evaluated by ECE or WES, plus program items such as recommendations or a statement of purpose. GRE or GMAT depends on the school.", "english": "Undergraduate and most graduate: TOEFL iBT 79 (or 4 on the new scale), IELTS 6.5, PTE 58, Duolingo 105, with section minimums. Waivers exist for listed countries.", "how_to_apply": "Apply online. Admissions are rolling and decisions take about 10 business days. Conditional admission is possible.", "deadlines": "Undergraduate fall: scholarship priority 1 March, outside US 15 July. Spring: priority 1 October, outside US 1 December. Graduate deadlines vary by program.", "application_fee": "$75 undergraduate and $75 graduate (waived if you use ECE or WES evaluation).", "documents": "Transcripts for all schools, translations, English proof. Graduate: ECE or WES evaluation.", "fees_link": "https://www.ucdenver.edu/international-admissions/costs-financial-aid/undergraduate", "sources": ["https://www.ucdenver.edu/international-admissions/apply-for-admission/undergraduate/first-year", "https://www.ucdenver.edu/international-admissions/apply-for-admission/graduate", "https://www.ucdenver.edu/international-admissions/costs-financial-aid/undergraduate"]}$q$::jsonb, admission_link = $q$https://www.ucdenver.edu/docs/librariesprovider208/default-document-library/final-version---ghana-nigeria-and-kenya-applicant-guide-pdf.pdf$q$, admission_checked = '2026-11-13' where id = 'b8bcf58f-9d86-4023-9131-a888fb2bf61f' and country = 'United States';
update schools set admission_info = $q${"ug": "Official high school transcript, exam results or diploma if applicable, and passport information.", "pg": "Official transcripts, English proof and passport copy. Financial documents are needed for the I-20.", "english": "Undergraduate full admission: TOEFL 61, IELTS 5.5, Duolingo 100.", "how_to_apply": "Apply online. International students may qualify for aid, scholarships and need-based scholarships, but the page names none.", "deadlines": "Undergraduate: fall 1 June, spring 1 November.", "application_fee": "$35 undergraduate.", "documents": "Online application, official transcript, exam results or diploma, passport information.", "fees_link": "https://www.pennwest.edu/affording-college/scholarships-grants/scholarships.php", "sources": ["https://www.pennwest.edu/admissions/international/undergraduate.php", "https://www.pennwest.edu/admissions/graduate/index.php"]}$q$::jsonb, admission_link = $q$https://www.pennwest.edu/affording-college/scholarships-grants/scholarships.php$q$, admission_checked = '2026-11-13' where id = 'df218d1f-d377-472d-9476-8a778a8674f9' and country = 'United States';
update schools set admission_info = $q${"ug": "Freshmen must be 17 by the first class day and have a 2.5 GPA in core subjects. SAT or ACT is optional but needed for the Freshman Merit Scholarship. Transfers send transcripts and course descriptions.", "pg": "Competitive review by departments. Details are on the graduate international page.", "english": "TOEFL iBT 71 or 4, IELTS 6.0, SAT 480 verbal, ACT English 20, PTE 54, Duolingo 110. African freshman applicants must prove English with one of the listed tests.", "how_to_apply": "Apply on the USM or Common application. Scholarship amounts for international students were not on the pages checked.", "deadlines": "Undergraduate fall 1 May, spring 1 October. Graduate deadlines vary.", "application_fee": "$45 undergraduate.", "documents": "Transcripts or exam results, English proof, fee. NACES evaluation for transfers.", "fees_link": "https://www.usm.edu/undergraduate-admissions/international-admissions/index.php", "sources": ["https://www.usm.edu/undergraduate-admissions/international-admissions/index.php"]}$q$::jsonb, admission_link = $q$https://www.usm.edu/undergraduate-admissions/international-admissions/index.php$q$, admission_checked = '2026-11-13' where id = '2c8e8919-0abc-437b-b1de-8fda88736e90' and country = 'United States';
update schools set admission_info = $q${"ug": "Freshmen need a 2.5 high school GPA for spring and summer 2027 and 3.0 from fall 2027. SAT or ACT is required (SAT EBRW 500 and Math 490, or ACT 18 and 18). Transfers need 30 semester hours and a 2.0 GPA.", "pg": "Foreign transcripts need an AICE or NACES course-by-course evaluation with GPA. Some programs ask more.", "english": "Undergraduate: TOEFL iBT 4 on the new scale (79 before), IELTS 6.0, Duolingo 115, PTE 58, SAT EBRW 500, ACT English 18. Graduate: TOEFL 80 and IELTS 6.5.", "how_to_apply": "Apply online, then have foreign records evaluated by a NACES or AICE member. Applicants who miss English minimums can start in the Intensive English Program.", "deadlines": "Fall 2027 priority 2 November 2026, regular 1 July 2027. Spring 2027: 16 November 2026. Summer 2027: 3 May.", "application_fee": "$40 undergraduate (free in November for international freshmen and transfers) and $60 graduate.", "documents": "Official transcripts, English evaluation of foreign records, SAT or ACT scores, English proof.", "fees_link": "https://www.kennesaw.edu/admissions/undergraduate/out-of-state-tuition/index.php", "sources": ["https://www.kennesaw.edu/admissions/undergraduate/admission-requirements/international.php", "https://www.kennesaw.edu/admissions/graduate/application-process/international.php", "https://www.kennesaw.edu/admissions/undergraduate/out-of-state-tuition/index.php"]}$q$::jsonb, admission_link = $q$https://www.kennesaw.edu/admissions/undergraduate/out-of-state-tuition/index.php$q$, admission_checked = '2026-11-13' where id = 'cc0694db-6519-4f07-a618-f17f0c70ab02' and country = 'United States';
update schools set admission_info = $q${"ug": "High school or college transcripts with English translation, English scores and financial documents through the portal. College transcripts need a NACES evaluation.", "pg": "Foreign records need a detailed transcript evaluation. Official transcripts are needed to finalize admission. Programs may have extra rules.", "english": "Undergraduate: TOEFL iBT 79 (before 20 Jan 2026) or 4.5 (after), IELTS 6.5, PTE 53, Duolingo 100. Graduate: TOEFL, IELTS or Duolingo (no minimums on the page).", "how_to_apply": "Apply online. International students on the page do not get a listed scholarship except a Non-Resident Award for Canadians and Mexicans.", "deadlines": "Undergraduate: fall 1 July, winter 1 November, summer 1 March. Graduate varies by program.", "application_fee": "Graduate $45. Undergraduate fee not listed.", "documents": "Transcripts, English scores, financial documents, evaluation for foreign college records.", "fees_link": "https://www.oakland.edu/futurestudents/apply/international/", "sources": ["https://www.oakland.edu/futurestudents/apply/international/", "https://www.oakland.edu/grad/how-to-apply/"]}$q$::jsonb, admission_link = $q$https://www.oakland.edu/futurestudents/apply/international/$q$, admission_checked = '2026-11-13' where id = '3218dcc0-2a1d-4f27-b027-bea3ec2b8f9f' and country = 'United States';
update schools set admission_info = $q${"ug": "Freshmen from US high schools need a 2.5 GPA (ACT 17 or SAT 930 if 2.50 to 2.79). Transfers need 2.0. WASSCE and WAEC credentials are exempt from course-by-course evaluation.", "pg": "Course-by-course evaluation from a NACES member showing bachelor's equivalency. Proof of funds for one year is needed for the I-20.", "english": "Undergraduate: IELTS 6.5, Duolingo 105, PTE 53, iTEP 3.8. Graduate: IELTS 6.5, Duolingo 110, PTE 67, TOEFL 4 (new scale). Scores under 2 years old.", "how_to_apply": "Apply online with fee and documents. UNCG lists only graduate assistantships and refers to EducationUSA for external funding.", "deadlines": "Dates are not on the page. Graduate deadlines vary by department.", "application_fee": "$65.", "documents": "Application, English scores, passport copy, official transcripts, evaluation for non-US records.", "fees_link": "https://admissions.uncg.edu/admissions/international-admissions/international-requirements/", "sources": ["https://admissions.uncg.edu/admissions/international-admissions/international-requirements/"]}$q$::jsonb, admission_link = $q$https://admissions.uncg.edu/admissions/international-admissions/international-requirements/$q$, admission_checked = '2026-11-13' where id = '464cacd4-1735-4486-aab1-6d3c8ae42fd6' and country = 'United States';
