update schools set admission_info = $q${"ug": "Application, fee, English proof, transcripts, passport copy and UNI Financial Statement. Rolling admission with decisions up to 15 business days.", "pg": "Undergraduate record equal to 2.75 GPA. Department decisions. Needs transcripts, English proof, passport copy, financial statement.", "english": "UNI accepts TOEFL, IELTS, Duolingo, and SAT or ACT. Score minimums were not on the pages checked. Conditional admission is possible.", "how_to_apply": "Apply online. Admitted students can also apply for the UNI scholarships.", "deadlines": "Undergraduate: rolling. Graduate: varies by program.", "application_fee": "$50 undergraduate and $75 graduate. No waiver, but a deferral request is possible.", "documents": "Application, fee, English proof, transcripts, passport page, UNI Financial Statement.", "fees_link": "https://admissions.uni.edu/international/undergraduate-students/scholarships", "sources": ["https://admissions.uni.edu/international/undergraduate-students", "https://admissions.uni.edu/international/graduate-studies", "https://admissions.uni.edu/international/frequently-asked-questions", "https://admissions.uni.edu/international/undergraduate-students/scholarships"]}$q$::jsonb, admission_link = $q$https://admissions.uni.edu/international/undergraduate-students/scholarships$q$, admission_checked = '2026-11-13' where id = '93256a1f-7b16-4a2a-b691-7746bb11d5ae' and country = 'United States';
