update schools set admission_info = $q${"ug": "Official transcripts, English proof unless exempt, and a financial statement for F-1. SAT or ACT needed if first-year weighted GPA is below 2.8.", "pg": "Three references, resume, GRE or GMAT (unless waived), NACES evaluated transcripts, English proof.", "english": "Undergraduate: TOEFL iBT 78, IELTS 6.0, Duolingo 100, SAT 500, ACT 20. Graduate: TOEFL 79, IELTS 6.5.", "how_to_apply": "First-year students use the Common App. The application also counts for scholarships.", "deadlines": "First-year fall: apply by 15 November (materials by 30 November) for most scholarships. Transfer 1 February. Graduate fall 1 February or 1 July.", "application_fee": "$65 undergraduate. Graduate fee not listed.", "documents": "Official transcripts, test scores, financial statement, translations.", "fees_link": "https://admissions.appstate.edu/apply/international-student", "sources": ["https://admissions.appstate.edu/apply/international-student", "https://graduate.appstate.edu/graduate-admissions/apply-graduate-school/international-graduate-applicant"]}$q$::jsonb, admission_link = $q$https://admissions.appstate.edu/apply/international-student$q$, admission_checked = '2026-11-13' where id = 'dd48585d-af93-4a98-890d-98e1c216273d' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply online. Freshman admission weighs your high school grades and English skills most. Transfer students need at least a 2.0 GPA.", "pg": "You need a US bachelor's degree or its equivalent. Master's programs need a 2.75 GPA and doctoral programs need a 3.0 GPA. Some departments ask for more.", "english": "Graduate minimums: TOEFL iBT 80 (4 for tests from January 2026), IELTS 6.5, PTE 59, Duolingo 110, or paper TOEFL 550. Undergraduate scores are on the school's English page. Scores must be less than two years old.", "how_to_apply": "Apply online and pay the fee. Upload your transcript or marks sheet. You usually hear back within 5 to 7 business days after the fee and transcript are in. The school lists no scholarship for international students on these pages.", "deadlines": "Not stated on the pages read. See the school's deadlines pages.", "application_fee": "$50 for undergraduate applicants. Graduate fee not stated on the page read.", "documents": "Official international transcript or marks sheet. English test scores. Transfer students need a course by course credential evaluation from a NACES or AICE agency.", "fees_link": "https://www.memphis.edu/admissions/basics/int-requirements.php", "sources": ["https://www.memphis.edu/admissions/basics/int-requirements.php", "https://www.memphis.edu/graduateadmissions/future/admission-requirements.php"]}$q$::jsonb, admission_link = $q$https://www.memphis.edu/admissions/basics/int-requirements.php$q$, admission_checked = '2026-11-13' where id = '59424828-7d34-41a8-8c74-76d73cd8f83d' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply with the international application. You need English test scores for full admission. You must show proof of financial support with a Financial Affidavit and bank statements.", "pg": "You need a bachelor's or master's degree from a US regionally accredited school or the equivalent. From August 1, 2026, international transcripts need a course by course evaluation from a NACES member.", "english": "Undergraduate general admission: TOEFL iBT 61 (3.5 on the 2026 scale), IELTS 6.0, Duolingo 95, PTE 44. Engineering and English majors need higher scores. TOEFL MyBest and IELTS Indicator are not accepted. Graduate minimums are on the graduate entrance exams page.", "how_to_apply": "Apply online, then submit the Financial Affidavit and bank statements through the iGlobal portal to get an I-20. Students who miss the English score may get conditional admission through the Intensive English Program. The school says to check MavLINK for scholarships and lists no named international scholarship.", "deadlines": "Each graduate program sets its own deadline. Undergraduate deadlines not stated on the pages read.", "application_fee": "Graduate degree-seeking fee is $50. Undergraduate fee not stated on the page read.", "documents": "Transcripts, Financial Affidavit, bank statements valid for 12 months, passport copy, English scores. Graduate programs may also ask for recommendation letters, GRE or GMAT, a resume or a statement of purpose.", "fees_link": "https://www.unomaha.edu/office-of-graduate-studies/admissions/how-to-apply-international.php", "sources": ["https://www.unomaha.edu/undergraduate-admissions/international-students/index.php", "https://www.unomaha.edu/undergraduate-admissions/international-students/english-proficiency.php", "https://www.unomaha.edu/office-of-graduate-studies/admissions/how-to-apply-international.php"]}$q$::jsonb, admission_link = $q$https://www.unomaha.edu/office-of-graduate-studies/admissions/how-to-apply-international.php$q$, admission_checked = '2026-11-13' where id = 'c6ccaed7-79a1-4b99-815f-aede7bfab49c' and country = 'United States';
update schools set admission_info = $q${"ug": "Submit the application, official transcripts in English and proof of English skills. Students who attend high school outside the US are directed to apply through INTO UAB.", "pg": "You need the equivalent of a US four year bachelor's degree. Transcripts must be official and stamped, with a separate degree statement. Non-US coursework needs a course by course evaluation. Programs may ask for GRE, GMAT or MAT, letters and an essay.", "english": "Undergraduate: TOEFL 77, IELTS 6.0 with 5.5 in each section, Duolingo 120. Graduate: TOEFL 80, IELTS 6.5, PTE 56, Duolingo 120. Scores must be less than two years old.", "how_to_apply": "Apply online and pay the fee. Undergraduates who live outside the US and attend a non-US high school are directed to INTO UAB. Graduate applicants who need an F-1 or J-1 also send a Financial Affidavit.", "deadlines": "Undergraduate priority: Fall June 1, Spring November 1, Summer May 15. Graduate degree-seeking: Fall August 1, Spring December 1, Summer May 1 (as listed for the 2026 and 2027 terms).", "application_fee": "$40 for undergraduate. $60 for international graduate applicants.", "documents": "Official transcripts, English test scores, degree statement, Financial Affidavit for graduate F-1 or J-1 applicants, program items such as letters and an essay.", "fees_link": "https://www.uab.edu/admissions/apply/international/freshman", "sources": ["https://www.uab.edu/admissions/apply/international/freshman", "https://www.uab.edu/graduate/admissions/international-applicants", "https://www.uab.edu/admissions/cost/scholarships/international-students"]}$q$::jsonb, admission_link = $q$https://www.uab.edu/admissions/apply/international/freshman$q$, admission_checked = '2026-11-13' where id = 'd0c99a84-bdec-4f0a-915e-b672d91741c3' and country = 'United States';
update schools set admission_info = $q${"ug": "First-time freshmen need a 3.0 out of 4.0 GPA or 80 percent average, a high school diploma, an English test and a passport copy. Transfer students need a 2.4 GPA. International transfer applicants cannot apply to Nursing.", "pg": "You need a degree from a recognized school that required at least 16 years of prior education, plus official records and proof of finances. Some programs ask for extra items.", "english": "Undergraduate: TOEFL iBT 64 (before January 21, 2026), IELTS 6.0, Duolingo 95, PTE 50. Graduate: TOEFL iBT 80 or paper 550, IELTS 6.5, PTE 65. Some graduate programs need higher scores.", "how_to_apply": "Apply on Cal State Apply and upload documents as PDFs to the International Admission Documents portal. The school lists no scholarship for international students on these pages.", "deadlines": "Fall 2027: apply October 1 to May 15, documents due May 30, 2027. Spring 2027: July 1 to October 4, documents due October 18, 2026. No summer or winter term.", "application_fee": "$70", "documents": "High school or college transcripts, diploma, English test, passport page. A financial affidavit is not needed for review but is encouraged to avoid I-20 delays.", "fees_link": "https://www.csus.edu/international-programs-global-engagement/application-admissions-process/undergraduate.html", "sources": ["https://www.csus.edu/international-programs-global-engagement/application-admissions-process/undergraduate.html", "https://catalog.csus.edu/admission/international/"]}$q$::jsonb, admission_link = $q$https://www.csus.edu/international-programs-global-engagement/application-admissions-process/undergraduate.html$q$, admission_checked = '2026-11-13' where id = 'd383d5eb-4a49-439c-b2e2-dbe050fec658' and country = 'United States';
update schools set admission_info = $q${"ug": "Submit all secondary or college transcripts and your diploma or leaving certificate, English proof, a passport page and financial papers for F or J visas. SAT and ACT are optional but recommended.", "pg": "Graduate requirements were not confirmed on the pages read.", "english": "TOEFL iBT 79 (4.5 for tests from January 21, 2026), paper TOEFL 550, IELTS 6.5, Duolingo 120, PTE 53. The page lists one set of scores for undergraduate and graduate. Conditional admission may be offered if only English is missing.", "how_to_apply": "Apply online and upload all documents to the portal. Documents must be official, sealed and stamped. Non-English records need a certified translation. F-1 and J-1 students attend the Norfolk campus.", "deadlines": "Undergraduate: Fall April 15, Spring October 1, Summer February 1.", "application_fee": "$50", "documents": "Transcripts, diploma or leaving certificate, certified translations, financial documents, passport page, English test scores.", "fees_link": "https://www.odu.edu/admission/international", "sources": ["https://www.odu.edu/admission/international", "https://www.odu.edu/admissions/proficiency"]}$q$::jsonb, admission_link = $q$https://www.odu.edu/admission/international$q$, admission_checked = '2026-11-13' where id = '3531fd46-6ad4-41db-bf21-cb5b10a221ae' and country = 'United States';
update schools set admission_info = $q${"ug": "For new freshmen with no prior college. You need official high school transcripts with a credential evaluation from a NACES member such as WES or ECE. You also need a financial guarantee covering one year.", "pg": "You need a final official undergraduate transcript showing your degree, evaluated by a NACES member. Some programs need GRE, GMAT or PRAXIS and recommendation letters. Some programs have their own steps.", "english": "Official TOEFL (code 1322), IELTS or ELS scores unless exempt. Minimum scores are on the school's Required Scores page.", "how_to_apply": "Apply online with your name as in your passport. Upload the financial guarantee and passport copy as supplemental materials and mail an original bank statement from your bank. Decisions take 4 to 6 weeks.", "deadlines": "Undergraduate priority: Fall June 1, Spring October 15. I-20 admission: Fall July 1, Spring November 15. Graduate priority: Fall June 1, Spring October 15, Summer February 15.", "application_fee": "$65 for undergraduate. Graduate fee amount not stated.", "documents": "Evaluated transcripts, financial guarantee, original bank statement, English scores, passport copy.", "fees_link": "https://www.indianastate.edu/admissions/international/international-freshman-admissions", "sources": ["https://www.indianastate.edu/admissions/international/international-freshman-admissions", "https://indianastate.edu/admissions/international/international-graduate-admissions"]}$q$::jsonb, admission_link = $q$https://www.indianastate.edu/admissions/international/international-freshman-admissions$q$, admission_checked = '2026-11-13' where id = '4006fb10-df11-4d20-a8f1-74d8992faa28' and country = 'United States';
update schools set admission_info = $q${"ug": "International applicants meet the same rules as US students. You need strong grades and a certificate that qualifies you for university in your home country. Report grades exactly as on your record.", "english": "Needed if fewer than three years of your secondary school were taught in English. Minimum scores are on the school's English Proficiency Requirement page.", "how_to_apply": "Apply with the UC application. First-year entry is fall only. Do not send extra documents with the application. If admitted you get instructions for official records. The page does not describe scholarships for international students.", "deadlines": "UC application filing period is October 1 to November 30 for fall entry.", "documents": "Official records are requested after admission. SAT and ACT are not considered.", "fees_link": "https://admissions.ucsc.edu/international-freshmen-admissions-requirements", "sources": ["https://admissions.ucsc.edu/international-freshmen-admissions-requirements"]}$q$::jsonb, admission_link = $q$https://admissions.ucsc.edu/international-freshmen-admissions-requirements$q$, admission_checked = '2026-11-13' where id = '9ea20e68-25a6-4c4e-97e2-3b768d647817' and country = 'United States';
update schools set admission_info = $q${"ug": "First-year: a standard high school diploma, 2.75 unweighted GPA and a C- or better in 4 years language arts, 3 math, 3 science and 3 social science. Transfer: 2.25 GPA and at least 24 semester credits.", "pg": "Graduate requirements beyond English scores are not listed on the page read. Contact the admissions office.", "english": "Undergraduate: TOEFL iBT 60, paper 500, IELTS 5.5, Duolingo 85, PTE 48. Graduate: TOEFL iBT 79, paper 550, IELTS 6.0, Duolingo 100, PTE 53. Exemptions include a degree from an English speaking country or a school taught in English.", "how_to_apply": "Complete the international student application and send the financial affidavit and documents. Admitted international students automatically get a Merit Award based on GPA.", "deadlines": "Fall 2027: application July 1, 2027 and confirmation August 1, 2027.", "documents": "Signed Financial Affidavit of Support, bank or sponsor papers, official transcripts with certified translations, English proof, passport page.", "fees_link": "https://wou.edu/international/admissions/", "sources": ["https://wou.edu/international/admissions/", "https://cdn.wou.edu/international/files/2025/04/Scholarship-Information_2025.pdf"]}$q$::jsonb, admission_link = $q$https://wou.edu/international/admissions/$q$, admission_checked = '2026-11-13' where id = 'fb6e1ee2-b6e1-4f1f-90e1-20e3611483bd' and country = 'United States';
update schools set admission_info = $q${"ug": "Reviewed one by one using your school courses, grades and test scores such as TOEFL, IELTS, Duolingo, ACT or SAT. Transfer students send records from every college attended.", "english": "Required. Accepted tests and scores are on the school's English Proficiency Requirements page.", "how_to_apply": "Apply online and pay the fee. Send documents by email or mail. Apply early because visa processing takes time.", "deadlines": "Fall: Early Action December 1, Regular May 1, Final July 15. Spring: Regular October 15, Final December 1.", "application_fee": "$50 one time, non-refundable", "documents": "High school or secondary school records, college records for transfers, all with English translations. Official transcripts after you finish school.", "fees_link": "https://admissions.d.umn.edu/apply/international-students/international", "sources": ["https://admissions.d.umn.edu/apply/international-students/international", "https://admissions.d.umn.edu/apply/international-students/costs"]}$q$::jsonb, admission_link = $q$https://admissions.d.umn.edu/apply/international-students/international$q$, admission_checked = '2026-11-13' where id = '84de265b-7062-4f3b-84ac-f7894e148aa9' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply online. Send official transcripts to one NACES approved credential evaluator. Prove English skills. After admission, show a Certificate of Finances before the I-20 is issued.", "english": "TOEFL iBT 61, IELTS 6.0, MET 55, iTEP 3.7, PTE 50, Duolingo 95. Other proof is accepted, such as a US high school diploma, an IB diploma from an English medium school, or SAT or ACT English scores. Scores are valid two years.", "how_to_apply": "Apply on the NMU application portal. Applications are taken all year. NMU has automatic awards for new international undergraduates, so no separate form is needed for those.", "deadlines": "Suggested and final: Fall April 15 and June 1. Winter September 1 and October 1.", "documents": "Transcripts evaluated by a NACES evaluator, English proof, Certificate of Finances.", "fees_link": "https://nmu.edu/internationalprograms/apply", "sources": ["https://nmu.edu/internationalprograms/apply", "https://nmu.edu/internationalprograms/scholarships"]}$q$::jsonb, admission_link = $q$https://nmu.edu/internationalprograms/apply$q$, admission_checked = '2026-11-13' where id = '8dfb99cc-c0d6-46d7-8c60-eee9fb15d1bb' and country = 'United States';
update schools set admission_info = $q${"ug": "Meet Hunter's freshman or transfer standards and show English skills. Get admitted before you apply for a visa. International students cannot apply to fully online or hybrid programs.", "pg": "Requirements vary by program. F-1 and J-1 applicants cannot apply to several programs, including all graduate Nursing programs.", "english": "Undergraduate: TOEFL iBT 61, paper 500, IELTS 6, Pearson 44. Conditional admission for English study is not offered.", "how_to_apply": "Use the freshman or transfer application. The school says Hunter College does not provide financial assistance to international students, so no scholarships are listed.", "documents": "Full secondary school record, diploma, any external exam certificates. Non-English documents need a word for word translation signed by a qualified translator.", "fees_link": "https://hunter-undergraduate.catalog.cuny.edu/admissions/international-admission", "sources": ["https://hunter-undergraduate.catalog.cuny.edu/admissions/international-admission", "https://www.hunter.cuny.edu/students/admissions/graduate-admissions/apply/international-applicants/"]}$q$::jsonb, admission_link = $q$https://hunter-undergraduate.catalog.cuny.edu/admissions/international-admission$q$, admission_checked = '2026-11-13' where id = '0edada69-3bee-4368-a313-544ca6f44c78' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply on the WIU application portal and send documents by email. Details of undergraduate rules were not on the page read.", "pg": "GRE or GMAT depends on the program. You may apply to at most two programs. Recommendation letters are preferred but not required.", "english": "Depends on your country of citizenship. See the school's Language Proficiency Requirements page.", "how_to_apply": "Submit the online application and fee. Email documents to international-ed@wiu.edu with your WIU ID. If admitted, send proof of funding. The I-20 comes by email.", "deadlines": "Graduate: Fall April 1, Spring October 1.", "application_fee": "$50 for graduate applicants. No fee waivers.", "documents": "Transcripts, recommendation letters if needed, GRE or GMAT if the program requires it, proof of funding after admission.", "fees_link": "https://www.wiu.edu/graduate_studies/international/faqadmissions.php", "sources": ["https://www.wiu.edu/graduate_studies/international/faqadmissions.php", "https://www.wiu.edu/global_studies/scholarships.php"]}$q$::jsonb, admission_link = $q$https://www.wiu.edu/graduate_studies/international/faqadmissions.php$q$, admission_checked = '2026-11-13' where id = 'eb290134-8f03-4cf0-bc03-8aa6e21b8acb' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply through ApplyTexas as a freshman. Automatic admission needs one of: top 30 percent of your class, ACT 21 or SAT 1060. Send official transcripts. A WES ICAP evaluation is needed for Nigeria transcripts or any transcript not in English.", "pg": "Follow the steps on your program page. Send official transcripts to the Graduate School. A WES ICAP evaluation is needed for Nigeria or non-English transcripts.", "english": "TOEFL iBT 79, computer 213 or paper 550. Exemptions include IELTS 6.0 and a C or better in ENG 1301 and 1302 at a US school.", "how_to_apply": "Apply online and finish all requirements at least three months before the term. After admission, send sponsor and bank statements to the Office of International Programs. Admitted students apply for scholarships through the myLeo portal. No named international scholarship is listed.", "deadlines": "Undergraduate: Fall May 1, Spring October 1, Summer March 1. The page also says 90 days before term, so confirm with admissions.", "documents": "Official transcripts, English scores, sponsor statement, bank statement. The page lists at least $33,601 USD as the bank balance.", "fees_link": "https://www.etamu.edu/international/undergrad/apply/", "sources": ["https://www.etamu.edu/international/undergrad/apply/", "https://www.etamu.edu/international/grad/apply/", "https://www.etamu.edu/international/undergrad/funding/"]}$q$::jsonb, admission_link = $q$https://www.etamu.edu/international/undergrad/apply/$q$, admission_checked = '2026-11-13' where id = 'cf15d37e-deb2-4a47-ac74-a08b62bb7604' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply through UMKC Application Management. Freshmen send transcripts, proof of graduation and a Statement of Purpose. Transfers send all college transcripts.", "pg": "Graduate requirements were not on the page read.", "english": "Required for applicants whose first language is not English. Some programs may offer conditional admission. Scores are on the English Proficiency Policy page.", "how_to_apply": "Apply online and pay the fee. After acceptance send your passport copy and a financial statement showing at least one year of funds. UMKC offers merit awards to F-1 students.", "deadlines": "Follow your program deadline. Otherwise rolling. Apply 3 to 4 months before the term.", "application_fee": "$75, plus a $50 international orientation fee for new degree-seeking students.", "documents": "Transcripts with line by line English translations, proof of English, Statement of Purpose, passport copy, financial statement. International transcripts are checked by an approved third-party service.", "fees_link": "https://catalog.umkc.edu/undergraduate-academic-regulations-information/undergraduate-admission-policy-procedures/policies-on-admission-of-international-students/policies-on-admission-of-international-students.pdf", "sources": ["https://catalog.umkc.edu/undergraduate-academic-regulations-information/undergraduate-admission-policy-procedures/policies-on-admission-of-international-students/policies-on-admission-of-international-students.pdf", "https://www.umkc.edu/international-students/future-students/scholarships.html"]}$q$::jsonb, admission_link = $q$https://catalog.umkc.edu/undergraduate-academic-regulations-information/undergraduate-admission-policy-procedures/policies-on-admission-of-international-students/policies-on-admission-of-international-students.pdf$q$, admission_checked = '2026-11-13' where id = 'b2b5a356-ae37-4af2-b61b-30d155bcba2a' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply with Common App or ApplyTexas. Freshmen send transcripts for grade 9 through at least grade 11 plus official final exam results such as GCE O and A Levels. Transfers send all university transcripts and syllabi.", "pg": "You need the equivalent of a US four year bachelor's degree and a 3.0 GPA is expected. UT Dallas does its own credential evaluation and does not accept outside evaluations.", "english": "Undergraduate and graduate: Duolingo 105, IELTS 6.5, PTE 67, TOEFL iBT 80 (for tests on or before January 26, 2026), paper TOEFL 550. Exemptions include a degree taught in English for graduate applicants. Scores must be under two years old.", "how_to_apply": "Apply online and upload your documents in the Applicant Portal. The school's pages read did not list a scholarship for international students.", "deadlines": "Freshman fall: priority December 1, regular May 1. Graduate deadlines are on the Deadlines and Fees page.", "application_fee": "$75 for freshmen. $75 for graduate applicants.", "documents": "Certified translations, transcripts, degree certificates, official English scores sent by the testing agency.", "fees_link": "https://enroll.utdallas.edu/freshman/deadlines-and-fees", "sources": ["https://enroll.utdallas.edu/apply/international-applicants", "https://enroll.utdallas.edu/freshman/deadlines-and-fees", "https://graduate-admissions.utdallas.edu/international-students"]}$q$::jsonb, admission_link = $q$https://enroll.utdallas.edu/freshman/deadlines-and-fees$q$, admission_checked = '2026-11-13' where id = 'cd67b07d-2c40-4092-bc4c-e06b747ddf59' and country = 'United States';
update schools set admission_info = $q${"ug": "Meet the UC subject requirements. Report all coursework exactly as on your record. Do not send transcripts with the application unless asked.", "english": "Needed if you have fewer than three years of English instruction. Accepted: IELTS 6.5, TOEFL iBT 80 (4.5 for tests from January 2026), Duolingo 115, ACT English 24, or others. Scores are valid two years.", "how_to_apply": "Apply with the UC application. Fall entry only. After you accept an offer, send official records and scores. The school says aid and scholarships for international students are very limited, so none are listed.", "deadlines": "Fall 2027 filing period: October 1 to November 30, 2026.", "documents": "After admission: official grade 9 to 12 records, graduation certificate, official exam results and English scores. Proof of first year funding after admission.", "fees_link": "https://admissions.sa.ucsb.edu/international", "sources": ["https://admissions.sa.ucsb.edu/international", "https://admissions.sa.ucsb.edu/english-language-proficiency"]}$q$::jsonb, admission_link = $q$https://admissions.sa.ucsb.edu/international$q$, admission_checked = '2026-11-13' where id = '30d6c7a5-5f72-463b-9535-c5c2cbedd82a' and country = 'United States';
update schools set admission_info = $q${"ug": "Freshmen send an official high school transcript or an evaluation with GPA, SAT or ACT scores and English proof. International transcripts must be evaluated by a NACES or AICE member.", "pg": "Online application, statement of purpose of 600 words or fewer, and a course by course evaluation of all prior coursework by an AICE or NACES member.", "english": "Undergraduate and graduate: TOEFL iBT 69 or 3.5 (undergraduate), IELTS 6, PTE 50 (53 for graduate), Duolingo 100 (110 for graduate). Some exemptions apply, including finishing all secondary school in English with a school letter.", "how_to_apply": "Apply online and pay the fee. After acceptance send the Affidavit of Financial Support, bank letter and passport copy. The pages read list no scholarship for international students.", "deadlines": "Undergraduate and graduate enforced: Fall June 15, Spring November 1. Summer March 15, generally not open to international undergraduates. Allow 60 days for documents.", "application_fee": "$50", "documents": "Transcript evaluation, English scores, affidavit, bank letter, passport copy.", "fees_link": "https://www.tarleton.edu/admissions/international-applicants/", "sources": ["https://www.tarleton.edu/admissions/international-applicants/", "https://tarleton.edu/graduate/future/international"]}$q$::jsonb, admission_link = $q$https://www.tarleton.edu/admissions/international-applicants/$q$, admission_checked = '2026-11-13' where id = 'a990fdb7-5f43-48b0-818f-002aef20370a' and country = 'United States';
update schools set admission_info = $q${"ug": "Use the Common Application or the SUNY Application. Some applicants need a credential evaluation if admissions asks.", "pg": "Deadlines vary by program. Requirements are on the graduate international page.", "english": "Minimum scores were not on the page read. See the First-Year Requirements page.", "how_to_apply": "Apply online. Applications are reviewed on a rolling basis. All accepted first-year international applicants are guaranteed $7,500 in scholarships.", "deadlines": "Undergraduate: Spring October 15 (until January 5 with a valid F-1). Fall May 1 (until August 3 with a valid F-1).", "application_fee": "$50", "documents": "Academic records. See the first-year, transfer and graduate international pages."}$q$::jsonb, admission_link = null, admission_checked = '2026-11-13' where id = '33e45b33-ea8a-4920-980b-3b8ac0ce8312' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply with the UMass Boston application or Common App. Send official school records, a counselor or teacher recommendation and a 500 word essay.", "pg": "You need the equivalent of a regionally accredited US bachelor's degree. Most three-year degrees do not qualify. Official transcripts must come from your school. The I-20 is not issued for part-time or online programs.", "english": "Undergraduate: TOEFL iBT 79 (before January 21, 2026), IELTS 6.0, Duolingo 105. Graduate: TOEFL 79, IELTS 6.0, PTE 53, Duolingo 105 for most programs. Some programs need more.", "how_to_apply": "Apply online and pay the fee. Incoming first-year international students are automatically reviewed for a merit scholarship.", "deadlines": "First-year: Fall Early Action I November 1, Early Action II January 1, Regular February 15. Spring December 15.", "application_fee": "$60 for undergraduate. Graduate fee not stated on the page read.", "documents": "School records with certified translations, recommendation letter, essay, English scores. Graduate: official transcripts sent directly by the school.", "fees_link": "https://www.umb.edu/admissions/international-students/apply-as-a-international-student/first-year/", "sources": ["https://www.umb.edu/admissions/international-students/apply-as-a-international-student/first-year/", "https://www.umb.edu/admissions/graduate-students/apply/international-graduate-applicants/", "https://www.umb.edu/financial-aid/undergraduate-financial-aid/international-undergraduate-students/"]}$q$::jsonb, admission_link = $q$https://www.umb.edu/admissions/international-students/apply-as-a-international-student/first-year/$q$, admission_checked = '2026-11-13' where id = 'db68d842-722d-428f-90f5-d86eea9ab5d2' and country = 'United States';
update schools set admission_info = $q${"ug": "Undergraduate and graduate applicants need the application and fee, English proof, a financial statement, official transcripts and a passport copy.", "pg": "Same list as undergraduate. Select graduate programs allow provisional admission through the American Language Institute.", "english": "Minimum scores are on the school's international admissions page. Applicants below the score may apply for provisional admission through the American Language Institute.", "how_to_apply": "Apply online. After admission, accept and pay the deposit. The Office of International Education then sends your admission packet. All degree-seeking F-1 and J-1 students are reviewed for a partial tuition waiver.", "documents": "Financial statement covering two semesters, bank statement or sponsor letter, sponsor affidavit, official transcripts, passport copy.", "fees_link": "https://iup.edu/international/students-scholars/students/faq-for-international-students.html", "sources": ["https://iup.edu/international/students-scholars/students/faq-for-international-students.html"]}$q$::jsonb, admission_link = $q$https://iup.edu/international/students-scholars/students/faq-for-international-students.html$q$, admission_checked = '2026-11-13' where id = 'f9b19054-aa53-4e44-9561-3b2d20e5ba73' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply through the CUNY application system. After acceptance, apply for your I-20 through the Office of International Students and Scholars. Rolling admissions.", "pg": "Requirements and deadlines vary by program. Submit the online graduate application, then apply for the I-20.", "english": "Undergraduate: minimum TOEFL 500. Graduate requirements vary by department.", "how_to_apply": "Apply online. Students applying from abroad should apply by the dates below. No scholarship details were on the page read.", "deadlines": "Applying from abroad: Fall February 1, Spring September 15.", "documents": "Acceptance letter and I-20. Full document list not on the page read.", "fees_link": "https://www.qc.cuny.edu/admissions/international-admissions/", "sources": ["https://www.qc.cuny.edu/admissions/international-admissions/"]}$q$::jsonb, admission_link = $q$https://www.qc.cuny.edu/admissions/international-admissions/$q$, admission_checked = '2026-11-13' where id = '3fdc63b2-2e16-44ff-82d5-b68361bdc0b1' and country = 'United States';
update schools set admission_info = $q${"ug": "Send a personal statement, a letter of recommendation, official transcripts from every school, a NACES evaluation of non-US college records and a passport copy. High school records are needed unless you have a year of full-time college study.", "english": "Regular admission: TOEFL iBT 71, IELTS 6, Duolingo 105. Conditional admission: TOEFL 55, IELTS 5, Duolingo 90, with the Castleton Campus Pathway Program. Scores must be from the past two years.", "how_to_apply": "Apply online with the fee or a fee waiver. Show financial certification to get the I-20. Competitive international scholarships exist for first bachelor's degree students.", "application_fee": "Required but amount not stated on the page read.", "documents": "Transcripts, evaluation, personal statement, recommendation, passport copy, financial certification.", "fees_link": "https://vermontstate.edu/admission/international-students/", "sources": ["https://vermontstate.edu/admission/international-students/", "https://vermontstate.edu/?p=15323"]}$q$::jsonb, admission_link = $q$https://vermontstate.edu/admission/international-students/$q$, admission_checked = '2026-11-13' where id = '59f07a01-8c24-4815-825c-d360088a1a63' and country = 'United States';
update schools set admission_info = $q${"ug": "For students with no college work. You need secondary records with at least 75 percent (2.5 GPA equivalent), the diploma, and a passport copy. Non-4.0 transcripts need an official evaluation and translation.", "english": "TOEFL iBT 71 (no section below 16), IELTS 6.0 (no section below 5.0), Duolingo 95, SAT EBRW 510, ACT English 18 and Reading 20, or ELS Level 112.", "how_to_apply": "Apply online with your intended major. Show finances with a bank statement of at least $34,745 USD. The page notes merit scholarships for freshmen but names none for international students.", "deadlines": "Summer May 1, Fall August 1, Spring December 1.", "documents": "Passport copy, secondary records, diploma, bank statement and account holder letter.", "fees_link": "https://www.eku.edu/admissions/?p=573", "sources": ["https://www.eku.edu/admissions/?p=573"]}$q$::jsonb, admission_link = $q$https://www.eku.edu/admissions/?p=573$q$, admission_checked = '2026-11-13' where id = '93238799-3b31-41d0-b43b-36d922855d9f' and country = 'United States';
update schools set admission_info = $q${"ug": "Non-California residents need a 3.00 GPA or higher in the required a-g courses with C- or better. Non-US schools need 2 years history or social science, 3 math and 2 science. IGCSE or O Level: five subjects at C or higher. IB: six subjects at 4 or higher. SAT and ACT are not used.", "pg": "You need a US four year bachelor's degree or equivalent, good standing and at least a 2.5 GPA. Departments may add requirements.", "english": "Undergraduate: TOEFL iBT 71 (4 on the new scale), IELTS 6.0, Duolingo 95. Graduate: TOEFL iBT 80 (4.5 on the new scale), IELTS 6.5, Duolingo 105. Waivers include 3 years of full time secondary school taught in English.", "how_to_apply": "Apply on Cal State Apply. Graduate: upload unofficial transcripts and send official ones by post. The pages read list no scholarship for international students.", "deadlines": "Graduate programs with deadlines after May 1 require international applicants to apply by May 1. Other dates are on the filing period page.", "documents": "Undergraduate: transcripts from grade 9 with translations. Graduate: transcripts and degree certificates in original language and English, plus a credential evaluation or marks verification.", "fees_link": "https://www.cpp.edu/admissions/international/freshmen.shtml", "sources": ["https://www.cpp.edu/admissions/international/freshmen.shtml", "https://www.cpp.edu/admissions/international/graduate.shtml"]}$q$::jsonb, admission_link = $q$https://www.cpp.edu/admissions/international/freshmen.shtml$q$, admission_checked = '2026-11-13' where id = 'e4f319a2-eaf7-4188-8286-78ef6da2dccf' and country = 'United States';
update schools set admission_info = $q${"ug": "First-time freshmen need secondary school records with a minimum 2.5 GPA. Transfer students need a 2.0 GPA. A $500 deposit is needed before the I-20 or DS-2019.", "pg": "Postsecondary records, usually with a 3.0 GPA. Programs may ask for GRE, GMAT or MAT, three recommendation letters, a statement of purpose and a resume.", "english": "Undergraduate: Duolingo 95, TOEFL 61 (3.5 on the new scale), IELTS 5.5, iTEP 3.6, PTE 44. Graduate: Duolingo 100, TOEFL 71, IELTS 6.0, iTEP 3.7, PTE 48. A US bachelor's degree exempts graduate applicants.", "how_to_apply": "Apply online and upload documents. Show a $500 non-refundable deposit. Some merit scholarships are decided at admission with no separate application.", "deadlines": "Priority, applying from outside the US: Fall April 1, Spring October 1, Summer March 1.", "application_fee": "$35 for undergraduate. $60 for graduate.", "documents": "Official records with certified translations, English scores, deposit. Records must have an original stamp or seal. Consolidated mark sheets are not accepted.", "fees_link": "https://art.southalabama.edu/departments/international/requirements-deadline.html", "sources": ["https://art.southalabama.edu/departments/international/requirements-deadline.html", "https://testit.southalabama.edu/departments/financialaffairs/scholarships/internationalstudents.html"]}$q$::jsonb, admission_link = $q$https://art.southalabama.edu/departments/international/requirements-deadline.html$q$, admission_checked = '2026-11-13' where id = 'f57bb834-9fbc-4e35-8968-cff2b459b7f1' and country = 'United States';
update schools set admission_info = $q${"ug": "You need a high school diploma or equivalent and a mean GPA of 89.5. SAT and ACT are optional. Send one recommendation letter and a GAP statement if you had a long break in schooling.", "pg": "Specific deadlines and requirements vary by program. See the graduate applicants page.", "english": "TOEFL 71, IELTS 6.0, PTE 55. Students below these levels must finish intensive English study on campus first.", "how_to_apply": "Apply with the SUNY Application or Common Application. Send bank statements and the signed SUNY International Student Financial Statement. The school says it offers merit scholarships to qualified international students but the page read gives no names or amounts.", "deadlines": "Rolling. Send complete materials by mid-May for Fall and mid-November for Spring.", "application_fee": "$50", "documents": "Official transcripts, recommendation letter, bank statement, financial statement, passport page.", "fees_link": "https://ww1.oswego.edu/admissions/undergraduate-admissions/how-apply/international-applicants", "sources": ["https://ww1.oswego.edu/admissions/undergraduate-admissions/how-apply/international-applicants", "https://ww1.oswego.edu/international/international-student-admissions"]}$q$::jsonb, admission_link = $q$https://ww1.oswego.edu/admissions/undergraduate-admissions/how-apply/international-applicants$q$, admission_checked = '2026-11-13' where id = '513da8b6-f3a6-4312-abc0-e77a5fd75f2e' and country = 'United States';
update schools set admission_info = $q${"ug": "Documents depend on your student type and your country. Send official documents to applyworldwide@uwosh.edu.", "pg": "Usually three recommendation letters. Official transcripts and degree certificates with a course by course NACES or AICE evaluation. Notarized Confidential Declaration of Financial Resources.", "english": "Students from countries where English is not the official language must show proof. Graduate: TOEFL 550 paper or 79 to 80 internet, IELTS 7.0. Undergraduate scores not stated on the page read.", "how_to_apply": "Apply online. You can apply for scholarships after admission at uwo.sh/scholarships. Titan Global Scholars is the international student scholarship program.", "deadlines": "Undergraduate: Summer April 15, Fall July 15, Spring December 1. Graduate: Fall March 1, Spring September 1.", "application_fee": "$56 for graduate applicants. Undergraduate fee not stated.", "documents": "Official transcripts, English proof, recommendation letters for graduate programs, financial declaration, TB screening report.", "fees_link": "https://www.uwosh.edu/gradstudies/admissions/international-students", "sources": ["https://www.uwosh.edu/admissions/international/frequently-asked-questions/", "https://www.uwosh.edu/gradstudies/admissions/international-students"]}$q$::jsonb, admission_link = $q$https://www.uwosh.edu/gradstudies/admissions/international-students$q$, admission_checked = '2026-11-13' where id = 'b7d8b224-e981-4fc9-9203-5668fe0c2d87' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply online with a personal essay. Send official secondary records from the school or national education ministry. A NACES credential evaluation is advised. SAT and ACT are optional.", "pg": "Official transcripts from every school and a course by course evaluation from a NACES or AACRAO member showing a US bachelor's equivalent.", "english": "Undergraduate and graduate: TOEFL iBT 79, paper 550, IELTS 6.5, Duolingo 95 (105 for graduate), PTE 59. Graduate applicants with a degree taught in English may be exempt. Applicants below the scores may enroll in the Intensive English Language Program.", "how_to_apply": "Apply online, send the Affidavit of Support to Global Engagement and other documents to admissions. The school says no financial aid is currently available to non-US graduate students, though assistantships may be possible.", "deadlines": "Undergraduate: Fall April 1, Spring November 1. Graduate: Fall June 1, Spring November 1.", "application_fee": "$50", "documents": "Transcripts, evaluation, essay, Affidavit of Support, passport copy.", "fees_link": "https://www.ccsu.edu/international-admissions/first-year-students", "sources": ["https://www.ccsu.edu/international-admissions/first-year-students", "https://www.ccsu.edu/internationaladmissions/graduate-students"]}$q$::jsonb, admission_link = $q$https://www.ccsu.edu/international-admissions/first-year-students$q$, admission_checked = '2026-11-13' where id = 'c46e33d4-f385-418b-a557-ee959e71f309' and country = 'United States';
update schools set admission_info = $q${"ug": "Freshmen send a secondary school certificate or diploma or West African Examinations Council results with a certified translation. Transfer students send a course by course evaluation. All need MMR immunization proof.", "pg": "Graduate requirements were not confirmed on the page read.", "english": "Undergraduate: IELTS 6.0, PTE 44, iTEP 3.9, Duolingo 110, ACT 19 in English and Reading, SAT 510 EBRW. The TOEFL iBT figure on the page looks like a typo, so confirm it with the school.", "how_to_apply": "Apply online with the fee and complete the Immigration Verification Form with a passport copy and bank letter. UA Little Rock lists no named scholarship for international students beyond department awards and the Donaghey Scholars Honors Program.", "deadlines": "Fall July 15, Spring November 15, Summer May 15.", "application_fee": "Required but amount not stated on the page read.", "documents": "Diploma or WAEC results with translation, MMR proof, English proof, passport copy, bank letter or financial statement.", "fees_link": "https://ualr.edu/policy/student/int-student-requirements/", "sources": ["https://ualr.edu/policy/student/int-student-requirements/", "https://ualr.edu/international/scholarships/"]}$q$::jsonb, admission_link = $q$https://ualr.edu/policy/student/int-student-requirements/$q$, admission_checked = '2026-11-13' where id = '04a7523d-1f23-494e-8cfb-f9f1c4b902fc' and country = 'United States';
update schools set admission_info = $q${"ug": "You need transcripts for all high school years with a minimum 2.0 GPA and your diploma. Transfer students need a 2.0 college GPA.", "pg": "Most programs need official transcripts, a diploma, a financial guarantee and a passport copy. Many programs have a minimum GPA and some ask for GRE, GMAT, recommendations or a statement of purpose.", "english": "Undergraduate: IELTS 6.0, TOEFL 71, Duolingo 100, PTE 51 for full admission. Conditional admission: IELTS 5.5, TOEFL 61, Duolingo 90. Citizens of listed countries including Ghana are exempt from submitting English scores. Most graduate programs: IELTS 6.0 or TOEFL 71.", "how_to_apply": "Apply online and pay the fee. Show a bank statement of at least $30,706 or a scholarship letter. The pages read describe no scholarship programs.", "deadlines": "Undergraduate: Spring 2027 November 15, Fall 2027 July 19.", "application_fee": "$100", "documents": "Transcripts, diploma, certified translations, bank statement dated within 6 months, passport copies.", "fees_link": "https://www.murraystate.edu/students/International/Admissions/", "sources": ["https://www.murraystate.edu/students/International/Admissions/", "https://www.murraystate.edu/students/International/graduate_requirements.aspx"]}$q$::jsonb, admission_link = $q$https://www.murraystate.edu/students/International/Admissions/$q$, admission_checked = '2026-11-13' where id = 'a67e16fa-d2f3-44ad-a6f0-fc706716605e' and country = 'United States';
update schools set admission_info = $q${"ug": "Admission is a two step process. First apply and send your academic records and English proof. Once approved, upload financial documents to get an I-20 or DS-2019.", "pg": "Requirements vary by program. See the program profile.", "english": "Required. The page read does not list scores. A TOEFL of 79 or equivalent is mentioned for one award.", "how_to_apply": "Apply online and send official academic records. STEM and Business programs close at the priority deadline. Other programs are rolling.", "deadlines": "Priority and final: Fall May 1 and June 1, Spring October 1 and November 1. Financial documents: Fall June 15, Spring November 15. Some graduate programs have earlier deadlines.", "documents": "Official academic credentials, English proof, financial documents for the I-20.", "fees_link": "https://www.siue.edu/admissions/international/how-to-apply/", "sources": ["https://www.siue.edu/admissions/international/how-to-apply/", "https://www.siue.edu/admissions/international/how-to-apply/application-deadlines.shtml"]}$q$::jsonb, admission_link = $q$https://www.siue.edu/admissions/international/how-to-apply/$q$, admission_checked = '2026-11-13' where id = 'b880c5e3-1a90-41da-9fd1-14f016e8eaec' and country = 'United States';
update schools set admission_info = $q${"ug": "International applicants meet the same rules as domestic applicants. For bachelor's programs you need a high school diploma, a 2.5 GPA and a 2.5 GPA in the 16 credit core. Use the SpanTran evaluation form for international transcripts.", "english": "TOEFL 79, IELTS 6.5, PTE 55, Duolingo 110 for undergraduate and 120 for graduate. Applicants from some English speaking countries are exempt.", "how_to_apply": "Apply online and send official transcripts. After admission, send the UAF Financial Statement for International Students and passport page for the I-20. The pages read do not list scholarships for international students.", "deadlines": "Fall June 15, Spring November 1, Summer May 1.", "application_fee": "Not stated. UAF offers fee waiver requests.", "documents": "Official transcripts, SpanTran evaluation for international transcripts, financial statement, passport page.", "fees_link": "https://www.uaf.edu/admissions/apply/international/", "sources": ["https://www.uaf.edu/admissions/apply/international/", "https://www.uaf.edu/admissions/apply/ug.php"]}$q$::jsonb, admission_link = $q$https://www.uaf.edu/admissions/apply/international/$q$, admission_checked = '2026-11-13' where id = '2151ba91-5fcf-4365-a04c-e394696f650c' and country = 'United States';
update schools set admission_info = $q${"ug": "You need official secondary school records and any college records, with certified English translations. SAT and ACT are not required for admission.", "pg": "You need a degree equal to a US bachelor's degree, official transcripts from every school, and a passport copy. Some programs also ask for GMAT, GRE or MAT scores, a statement of purpose, a CV or 2 to 3 recommendation letters.", "english": "Undergraduate: IELTS 6.0 or PTE 53. Duolingo has no stated minimum (100 or more is most competitive). Graduate: TOEFL 79, IELTS 6.0, PTE 53. Waivers are possible in some cases.", "how_to_apply": "Apply to the Office of Admission, get your applicant ID, pay the fee, then send your documents. After admission you give financial documents for the I-20. The pages read list no scholarship open to Ghana students.", "deadlines": "Fall June 1, Spring October 1, Summer May 1. Documents must be received by these dates.", "application_fee": "$75, non-refundable.", "documents": "Transcripts with certified English translations, sponsor letter and bank statement in US dollars (undergraduate), passport copy, test scores where the program asks.", "fees_link": "https://www.tamuk.edu/enrollment-management/admission/future-students/international/index.html", "sources": ["https://www.tamuk.edu/enrollment-management/admission/future-students/international/index.html", "https://www.tamuk.edu/enrollment-management/admission/graduate/international.html"]}$q$::jsonb, admission_link = $q$https://www.tamuk.edu/enrollment-management/admission/future-students/international/index.html$q$, admission_checked = '2026-11-13' where id = '2e233e53-1517-4275-bbdb-80e71dfc92a9' and country = 'United States';
update schools set admission_info = $q${"ug": "Required items are the online application, evaluated academic records, English proof, financial information and passport and visa details. Essay, recommendation letter and SAT or ACT are optional, but SAT or ACT is needed for honors scholarships.", "english": "IELTS or TOEFL is needed unless you have 24 or more transferable credits from a US regionally accredited school. Minimum scores were not found on the pages read.", "how_to_apply": "Submit the online application with all documents. Applications are not reviewed until complete, and I-20s are not issued before then. Original documents go by mail to the admissions office. International students can get honors scholarships at admission with no separate application.", "deadlines": "Fall December 1, Spring August 31 (completed application packet).", "documents": "Evaluated academic records, English test results, financial information, passport copy.", "fees_link": "https://www.morgan.edu/office-of-undergraduate-admission-and-recruitment/how-to-apply/international-applicants/application-deadlines", "sources": ["https://www.morgan.edu/office-of-undergraduate-admission-and-recruitment/how-to-apply/international-applicants/application-requirements", "https://www.morgan.edu/office-of-undergraduate-admission-and-recruitment/how-to-apply/international-applicants/faqs", "https://www.morgan.edu/office-of-undergraduate-admission-and-recruitment/how-to-apply/international-applicants/application-deadlines"]}$q$::jsonb, admission_link = $q$https://www.morgan.edu/office-of-undergraduate-admission-and-recruitment/how-to-apply/international-applicants/application-deadlines$q$, admission_checked = '2026-11-13' where id = '88cb5536-a66d-4458-b385-058f0a9b0f2b' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply as International on ApplyTexas. Freshmen need a document-by-document evaluation of their high school work with a US GPA. Transfer students need evaluations of their college work.", "english": "TOEFL, IELTS or PTE is accepted. Minimum scores were not listed on the page. Exemptions exist for some countries or for English Composition I and II with a B or better at a US school.", "how_to_apply": "Apply on ApplyTexas as International, send your evaluations and English scores, and you get an admit notice by email within 24 hours of a decision. After admission send proof of funds and your passport for the I-20. Graduate applicants are considered automatically for a $1,000 per year scholarship.", "documents": "Credential evaluation, English test scores, financial guarantee, passport copy.", "fees_link": "https://lamar.edu/international-education/international-admissions/undergraduate-intl-admissions/frequently-asked-questions.html", "sources": ["https://lamar.edu/international-education/international-admissions/undergraduate-intl-admissions/frequently-asked-questions.html", "https://lamar.edu/international-education/international-students-and-scholars/finance-issues.html"]}$q$::jsonb, admission_link = $q$https://lamar.edu/international-education/international-admissions/undergraduate-intl-admissions/frequently-asked-questions.html$q$, admission_checked = '2026-11-13' where id = '89c1732f-bc83-4014-b92a-7bcfe7108674' and country = 'United States';
update schools set admission_info = $q${"ug": "Meet UCA academic requirements. SAT and ACT are not required. If you meet academic rules but not English rules you are admitted to the Intensive English Program.", "pg": "Graduate applicants with a US bachelor's degree or higher do not need TOEFL. Some departments ask TOEFL from all non-native speakers.", "english": "TOEFL or IELTS scores are valid for two years. Minimum scores were not listed on the page read.", "how_to_apply": "Apply, then show proof of funds before UCA issues the I-20. Health insurance and orientation are required. Merit scholarships are decided by holistic review without SAT or ACT scores. Freshmen must live on campus.", "application_fee": "$50, rarely waived for international students.", "fees_link": "https://uca.edu/global/frequently-asked-application-questions", "sources": ["https://uca.edu/global/frequently-asked-application-questions"]}$q$::jsonb, admission_link = $q$https://uca.edu/global/frequently-asked-application-questions$q$, admission_checked = '2026-11-13' where id = '8e4ccd03-4bfd-46fc-ab32-8cf71546b54c' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply with the Common App (or transfer application). Non-US transcripts need a NACES-type evaluation with US equivalency, course-by-course grades and English translation.", "english": "TOEFL iBT 79, IELTS 6.5, Duolingo 110. Waived only for native English speakers applying from English-speaking countries.", "how_to_apply": "Submit the application, transcripts, English scores and the Financial Declaration Form. You must show money for the full cost before an I-20. International students are not eligible for RIC merit scholarships and RIC says it currently offers none for them. Tuition is the out-of-state rate.", "deadlines": "Early Action December 15, Spring entry December 15, Regular Decision March 15 (rolling after).", "application_fee": "$50, non-refundable. No fee waivers.", "documents": "Evaluated transcripts, English scores, Financial Declaration Form.", "fees_link": "https://www.ric.edu/admissions-financial-aid/undergraduate-admission/international-student-admission", "sources": ["https://www.ric.edu/admissions-financial-aid/undergraduate-admission/international-student-admission"]}$q$::jsonb, admission_link = $q$https://www.ric.edu/admissions-financial-aid/undergraduate-admission/international-student-admission$q$, admission_checked = '2026-11-13' where id = 'c55d1999-efb4-4128-ac99-4e7cbb81aef1' and country = 'United States';
update schools set admission_info = $q${"ug": "More than 55 bachelor's programs. Requirements and deadlines are on the Office of Admissions international page. Limited-access majors have separate deadlines.", "pg": "Requirements are set by each program. Most applicants with a non-US bachelor's degree need a course-by-course credential evaluation. Some programs are exempt, including all College of Computing, Engineering and Construction programs.", "how_to_apply": "You must be admitted to a full-time, on-campus, degree-seeking program to get an I-20. Online, part-time and certificate programs do not qualify. Merit tuition waivers, a limited number of International Center scholarships and graduate assistantships exist.", "fees_link": "https://www.unf.edu/intlctr/international-students/degree-seeking.html", "sources": ["https://www.unf.edu/intlctr/international-students/degree-seeking.html", "https://www.unf.edu/intlctr/international-students/scholarship.html"]}$q$::jsonb, admission_link = $q$https://www.unf.edu/intlctr/international-students/degree-seeking.html$q$, admission_checked = '2026-11-13' where id = 'ee6dbb42-c95d-4fda-a324-6d64f2cda922' and country = 'United States';
update schools set admission_info = $q${"ug": "Submit the online application, official high school and college transcripts with a US evaluation (for example WES), the financial guarantee form, the international student data form and a passport copy. Show at least $40,288 in bank-certified funds.", "english": "Any one: TOEFL 79 to 80 (iBT), IELTS 6.5, Duolingo 105, PTE 53, SAT Reading 400, or six credit hours of US college English. Countries where English is official and the teaching language are exempt.", "how_to_apply": "Apply online and send all documents before the final deadline. The scholarships page says N.C. A&T does not offer scholarships specifically for international students; departmental awards and graduate assistantships may be possible.", "deadlines": "Fall April 1, Spring October 1.", "documents": "Transcripts, credential evaluation, English proof, financial guarantee form, international data form, passport copy.", "fees_link": "https://ncat.edu/admissions/undergraduate/international-admissions.php", "sources": ["https://ncat.edu/admissions/undergraduate/international-admissions.php", "https://ncat.edu/admissions/financial-aid/types-of-aid/scholarships/international-student-scholarships.php"]}$q$::jsonb, admission_link = $q$https://ncat.edu/admissions/undergraduate/international-admissions.php$q$, admission_checked = '2026-11-13' where id = '0589a80c-a568-4c2f-8425-0cc7428347b9' and country = 'United States';
update schools set admission_info = $q${"ug": "First-year applicants need official school records, SAT or ACT (or the No Test option), an essay, a letter of recommendation and English proof. Records not in English need notarized translation. Transfer applicants need WES course-by-course evaluation and course descriptions.", "english": "First-year: TOEFL iBT 79, IELTS 6.5, Duolingo 110, PTE 61. Transfer: PTE 56, others the same. Some applicants can waive the test, for example if their school teaches in English or they follow Cambridge IGCSE or A-Levels with written verification.", "how_to_apply": "Apply with the UMass Lowell or Common Application and send documents. The page lists no international scholarships.", "deadlines": "First-year: Spring December 1, Fall July 25. Transfer: Spring January 7, Fall July 25.", "application_fee": "$70.", "documents": "School records, test scores, essay, recommendation, English proof, WES evaluation (transfer).", "fees_link": "https://www.uml.edu/international-applicants/application-requirements/international-undergrad-admissions.aspx", "sources": ["https://www.uml.edu/international-applicants/application-requirements/international-undergrad-admissions.aspx"]}$q$::jsonb, admission_link = $q$https://www.uml.edu/international-applicants/application-requirements/international-undergrad-admissions.aspx$q$, admission_checked = '2026-11-13' where id = '07ad6eb6-47ee-4666-bb9f-6e0a40ed6944' and country = 'United States';
update schools set admission_info = $q${"ug": "Send copies of all upper secondary and exam records with certified English translations, proof of English, and proof of $38,292 for the first year. Transfer applicants also send college records and course descriptions if they want credit.", "pg": "Send records from all earlier colleges with translations, English proof, and proof of $36,562 for the first year. Some programs are closed to international applicants, including Accounting, all certificates and School Leadership.", "english": "Proof of English is required. Minimum scores are on the CSUDH English Proficiency page, which was not read.", "how_to_apply": "Apply through Cal State Apply, then upload each packet as one PDF to the International Applicant Dropbox with the coversheet. Official records are due as soon as possible after admission. No international scholarship was found on the page.", "deadlines": "Undergraduate Fall: apply May 1, documents June 1. Spring: apply November 1, documents November 29. Graduate deadlines vary by program.", "documents": "Academic records, translations, English proof, financial proof, affidavit of support if sponsored, passport copy.", "fees_link": "https://csudh.edu/future-students/international/required-documentation", "sources": ["https://csudh.edu/future-students/international/required-documentation"]}$q$::jsonb, admission_link = $q$https://csudh.edu/future-students/international/required-documentation$q$, admission_checked = '2026-11-13' where id = '244c13a4-3cde-4dc6-906a-deea624d21bc' and country = 'United States';
update schools set admission_info = $q${"ug": "Send official secondary school records with certified translation if not in English. Transcripts must come from accredited schools.", "english": "TOEFL iBT 61 (paper 500), ELS level 112, ACT 19 in Reading and English, SAT 500 in evidence-based reading, or two semesters of US college English composition with C- or better. Scores are valid two years.", "how_to_apply": "Apply, pay the fee if asked, and send documents. ETSU sends a decision within five business days of deciding. International merit scholarships are given automatically at admission.", "application_fee": "A one-time non-refundable fee may apply. The amount was not listed.", "fees_link": "https://calendar.etsu.edu/policies/documents/international-applicants-undergraduate-admissions-policy.pdf", "sources": ["https://calendar.etsu.edu/policies/documents/international-applicants-undergraduate-admissions-policy.pdf", "https://www.etsu.edu/international/scholarships/merit.php"]}$q$::jsonb, admission_link = $q$https://calendar.etsu.edu/policies/documents/international-applicants-undergraduate-admissions-policy.pdf$q$, admission_checked = '2026-11-13' where id = '4437d041-4381-439b-b126-5f3d816e9f90' and country = 'United States';
update schools set admission_info = $q${"ug": "International freshmen need a US-equivalent GPA of at least 2.0, English proof and a foreign credential evaluation. Unofficial copies are accepted for admission, official ones after you are admitted.", "how_to_apply": "Apply, upload documents, and pay the fee. After admission, activate your student account and complete the General Scholarship application, which is reviewed for all WT scholarships. Scholarships of $1,000 or more per year can lower your tuition rate.", "application_fee": "$90, non-refundable, no waivers.", "documents": "English score reports sent by the testing agency, foreign credential evaluation sent by the agency, transcripts, high school completion certificate, certified translations.", "fees_link": "https://wtamu.edu/student-support/international-student-services/Applicants/INSTRUCTIONS%20TO%20APPLY/international-undergraduate.html", "sources": ["https://wtamu.edu/student-support/international-student-services/Applicants/INSTRUCTIONS%20TO%20APPLY/international-undergraduate.html"]}$q$::jsonb, admission_link = $q$https://wtamu.edu/student-support/international-student-services/Applicants/INSTRUCTIONS%20TO%20APPLY/international-undergraduate.html$q$, admission_checked = '2026-11-13' where id = 'e8bc7b7a-4271-4763-88e7-a0218f6011dd' and country = 'United States';
update schools set admission_info = $q${"english": "Minimum scores were not listed on the page read.", "how_to_apply": "Deadlines depend on program and start term. Documents not in English need a professional translation. If you do not meet English rules you can be conditionally admitted to the American English Language Program. International scholarships could not be confirmed on the pages read.", "documents": "Documents are listed on the NKU international undergraduate and graduate pages. Proof of funds is needed before the I-20.", "fees_link": "https://advservices.nku.edu/admissions/international/prospective-students/apply/faq.html", "sources": ["https://advservices.nku.edu/admissions/international/prospective-students/apply/faq.html", "https://keyrequest.nku.edu/admissions/international/prospective-students/scholarships-finances.html"]}$q$::jsonb, admission_link = $q$https://advservices.nku.edu/admissions/international/prospective-students/apply/faq.html$q$, admission_checked = '2026-11-13' where id = '330fdc55-af66-400b-ac21-c63fb3c39a69' and country = 'United States';
update schools set admission_info = $q${"ug": "You need an online application with a 500-word essay and a document-by-document evaluation of your high school record by a NACES member. The average incoming GPA is 2.7 on a 4.0 scale.", "english": "TOEFL 72 iBT, IELTS 6, ELS level 112, SAT 900 (reading and math), or ACT 19.", "how_to_apply": "Apply online with the fee and send official transcripts and evaluations directly to Admissions. Decision comes 3 to 4 weeks after your application is complete. A $200 confirmation deposit holds your place. No scholarship was listed on the page.", "deadlines": "No date listed. SCSU suggests starting five months before your term.", "application_fee": "$50.", "documents": "Essay, credential evaluation, official transcripts, English proof.", "fees_link": "https://www.southernct.edu/admissions/undergraduate/international/freshmen", "sources": ["https://www.southernct.edu/admissions/undergraduate/international/freshmen"]}$q$::jsonb, admission_link = $q$https://www.southernct.edu/admissions/undergraduate/international/freshmen$q$, admission_checked = '2026-11-13' where id = '4f1aa00f-420f-44bd-a95a-5c9d66ef4d7f' and country = 'United States';
update schools set admission_info = $q${"ug": "Freshmen (0 to 11 college credits) need a high school transcript with credential evaluation and SAT, ACT or CLT scores. Transfer students need a college GPA of at least 2.00. UWF uses holistic review.", "english": "Under 60 credits: SAT or ACT scores. 60 or more credits: TOEFL 79 (4.5 for tests on or after January 21, 2026), IELTS 6.0, Duolingo 110, PTE 53, or a C in college English composition.", "how_to_apply": "Apply, send evaluated records, then complete the financial documents for the I-20. Funds must be certified by a bank. Health insurance is required. No scholarship details were found on the pages read.", "deadlines": "Fall June 1, Spring November 1, Summer April 1.", "application_fee": "A non-refundable fee is required; the amount was not listed.", "documents": "Transcripts, credential evaluation, English proof, immunization form, bank-certified financial proof, insurance proof.", "fees_link": "https://uwf.edu/admissions/undergraduate/apply/international/requirements/", "sources": ["https://uwf.edu/admissions/undergraduate/apply/international/requirements/", "https://catalog.uwf.edu/undergraduate/admissions/internationalundergraduateadmissions/"]}$q$::jsonb, admission_link = $q$https://uwf.edu/admissions/undergraduate/apply/international/requirements/$q$, admission_checked = '2026-11-13' where id = '778a19e1-9a10-4224-9735-8f1d58fa34bb' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply online as Freshman or Transfer. Send official secondary records. Non-US college records need a NACES-credentialed course-by-course evaluation.", "english": "English proof is required. Minimum scores are on a separate Towson page that was not read.", "how_to_apply": "Apply, pay the fee and send your file. After you pay the enrollment deposit, the I-20 is processed. International students pay out-of-state tuition. Scholarship names were not found on the pages read.", "deadlines": "Fall freshman: November 1 (Early Action, Honors College, merit scholarships), February 1 (regular and international scholarships), June 1 (late, international only). Fall transfer: March 1 early, June 1 regular. Spring: November 1 freshman, November 15 transfer.", "application_fee": "$50, non-refundable.", "documents": "Secondary records, credential evaluation for non-US college work, English proof.", "fees_link": "https://catalog.towson.edu/undergraduate/admissions/international-undergraduate-admissions/", "sources": ["https://catalog.towson.edu/undergraduate/admissions/international-undergraduate-admissions/"]}$q$::jsonb, admission_link = $q$https://catalog.towson.edu/undergraduate/admissions/international-undergraduate-admissions/$q$, admission_checked = '2026-11-13' where id = 'e4bad281-7a1d-4986-abe2-b4d5b6d83e72' and country = 'United States';
update schools set admission_info = $q${"ug": "Upload transcripts (unofficial PDFs accepted at application), English proof and a passport copy. SAT or ACT is optional and can help with scholarships and placement.", "how_to_apply": "Apply, pay the fee, then after admission send a financial affidavit and proof of finances. International scholarships are given at admission with no separate application. No tuition deposit is needed.", "application_fee": "$60, non-refundable.", "documents": "Transcripts, English scores, passport copy (valid six months past start), financial affidavit and bank proof.", "fees_link": "https://semo.edu/international/admissions/freshman", "sources": ["https://semo.edu/international/admissions/freshman", "https://semo.edu/student-support/financial-services/financial-aid/international-scholarships"]}$q$::jsonb, admission_link = $q$https://semo.edu/international/admissions/freshman$q$, admission_checked = '2026-11-13' where id = 'f7f80dff-f70e-4bac-af69-eb0cdf40f7d2' and country = 'United States';
update schools set admission_info = $q${"ug": "First-year applicants send official English-translated records from all secondary and later schools. Transfer applicants usually need a GPA of 2.5 or higher (2.0 may be considered). Non-US coursework may need an evaluation by WES, IERF, ECE or TEC.", "english": "TOEFL iBT 70 (4 on new scale), IELTS 5.5, Duolingo 95, PTE 46, SAT 980 or ACT 20. Exempt countries include Australia, Canada (not Quebec), Ireland, Jamaica, New Zealand, South Africa and the UK.", "how_to_apply": "Apply online with the fee and upload unofficial copies first. Send later documents to internationaladmissions@commonwealthu.edu. The page lists no international scholarships.", "deadlines": "First-year: Fall June 1, Spring November 1. Transfer: Fall June 15, Spring November 15.", "application_fee": "$35, non-refundable.", "documents": "Translated academic records, English proof, credential evaluation if asked.", "fees_link": "https://commonwealthu.edu/admissions/how-to-apply/international-students", "sources": ["https://commonwealthu.edu/admissions/how-to-apply/international-students"]}$q$::jsonb, admission_link = $q$https://commonwealthu.edu/admissions/how-to-apply/international-students$q$, admission_checked = '2026-11-13' where id = '6cccc55d-96c6-444e-bd14-d19fbccc4f61' and country = 'United States';
update schools set admission_info = $q${"pg": "MBA applicants need a four-year bachelor's degree or equal, full-time study of at least 6 credits per semester, and GMAT, a portfolio, or an earlier master's degree. Also a resume and a 2 to 5 page personal statement.", "english": "MBA: TOEFL iBT 76 or IELTS 6.0. Scores older than two years are not accepted.", "how_to_apply": "Apply, send evaluated transcripts (WES, ECE or SpanTran), bank proof within six months of class start and the affidavit of financial support. Undergraduate details and scholarships were not confirmed.", "deadlines": "MBA international: Fall May 1, Spring October 15 (priority).", "application_fee": "$50, non-refundable (MBA).", "documents": "Transcripts with NACES evaluation, resume, personal statement, financial documents.", "fees_link": "https://www.msudenver.edu/mba/admissions/international-student-resources/", "sources": ["https://www.msudenver.edu/mba/admissions/international-student-resources/"]}$q$::jsonb, admission_link = $q$https://www.msudenver.edu/mba/admissions/international-student-resources/$q$, admission_checked = '2026-11-13' where id = '0a944e78-26e0-47a2-8d79-7fbb086b1466' and country = 'United States';
update schools set admission_info = $q${"ug": "Meet general admission rules and show English proficiency. WCU may ask for a credential evaluation (ECE, Josef Silny or WES).", "english": "TOEFL 80 iBT (550 paper, 4.5 new scale), IELTS Academic 6.0. Duolingo, SAT or ACT are also accepted; no minimums were listed.", "how_to_apply": "Apply online, send documents, and show proof you can pay all costs before immigration documents are issued. US health insurance is required. The page lists no scholarships.", "deadlines": "Fall May 1, Spring October 15.", "application_fee": "An application fee is required; the amount was not listed.", "documents": "Application, academic documents, credential evaluation if asked, financial proof, insurance proof.", "fees_link": "https://catalog.wcupa.edu/general-information/admissions-enrollment/undergraduate-admissions/international-student-admissions/", "sources": ["https://catalog.wcupa.edu/general-information/admissions-enrollment/undergraduate-admissions/international-student-admissions/"]}$q$::jsonb, admission_link = $q$https://catalog.wcupa.edu/general-information/admissions-enrollment/undergraduate-admissions/international-student-admissions/$q$, admission_checked = '2026-11-13' where id = '732af58b-3f09-4e1b-a7c8-2660d08514ec' and country = 'United States';
update schools set admission_info = $q${"how_to_apply": "Apply through International Admissions (international@unco.edu). Requirements, English minimums, fee and scholarships could not be confirmed on the pages read.", "deadlines": "Undergraduate: Fall June 15, Spring November 30, Summer March 29. Graduate deadlines vary by program.", "fees_link": "https://unco.edu/international-admissions/explore-unc/admission-requirements.aspx", "sources": ["https://unco.edu/international-admissions/explore-unc/admission-requirements.aspx", "https://unco.edu/international-admissions/explore-unc/cost-of-attendance-and-scholarships.aspx"]}$q$::jsonb, admission_link = $q$https://unco.edu/international-admissions/explore-unc/admission-requirements.aspx$q$, admission_checked = '2026-11-13' where id = '3f0f23f6-c16e-4168-abe3-44341897b1fc' and country = 'United States';
update schools set admission_info = $q${"pg": "Your degree must equal a 4-year US bachelor's degree. Some programs accept a 3-year degree with a WES evaluation. A WES evaluation is needed for 3-year degrees and second bachelor's degrees. Some departments ask for GRE, GMAT or recommendation letters.", "how_to_apply": "Upload unofficial documents through the link emailed to you. Official records are asked only after an offer. Financial aid is not available to international students, but some merit-based Pioneer Scholarships exist for admitted international students. English minimums, deadlines and fee were not confirmed.", "documents": "Unofficial academic records first, official records after admission, WES evaluation where needed.", "fees_link": "https://www.csueastbay.edu/iao/faq/index.html", "sources": ["https://www.csueastbay.edu/iao/faq/index.html"]}$q$::jsonb, admission_link = $q$https://www.csueastbay.edu/iao/faq/index.html$q$, admission_checked = '2026-11-13' where id = '51b551f6-398f-4c96-a715-f623993fb50d' and country = 'United States';
update schools set admission_info = $q${"ug": "Send the application, official transcripts from every school, a passport copy and course syllabi for courses taken outside the US. SAT or ACT is used for scholarship eligibility if you have it.", "english": "TOEFL iBT 61, IELTS Academic 5.5, PTE Academic 44. Scores must be under two years old. Other tests like Duolingo are accepted; check the Northwest website for their scores.", "how_to_apply": "Apply and pay the fee. Before the I-20, send a sponsor statement of support and a bank statement. Scholarship amounts were not given on the page read.", "application_fee": "$75, non-refundable.", "documents": "Transcripts with translation, syllabi, passport, sponsor statement, bank statement.", "fees_link": "https://nwmissouri.smartcatalogiq.com/en/2023-2024/undergraduate-catalog/admissions/international-student-admissions/new-international-students", "sources": ["https://nwmissouri.smartcatalogiq.com/en/2023-2024/undergraduate-catalog/admissions/international-student-admissions/new-international-students"]}$q$::jsonb, admission_link = $q$https://nwmissouri.smartcatalogiq.com/en/2023-2024/undergraduate-catalog/admissions/international-student-admissions/new-international-students$q$, admission_checked = '2026-11-13' where id = 'fad0dc8c-c50d-48e8-82f9-b7d801ee2c97' and country = 'United States';
update schools set admission_info = $q${"ug": "Transcripts must be evaluated by WES or ECE (course-by-course with US GPA). Start at least 90 days before classes begin.", "english": "TOEFL 79, IELTS 6.5, SAT 800, ACT 17, or the DSU English Language Institute certificate.", "how_to_apply": "Apply online, send evaluated transcripts and test scores, then the I-20 application and F-1 financial statement. The page lists no scholarships for international students.", "deadlines": "Spring 2027: October 11. Fall 2027: May 25.", "documents": "Evaluated transcripts, test scores, I-20 application, F-1 financial statement, affidavit of support for room and board.", "fees_link": "https://www.desu.edu/admissions/international", "sources": ["https://www.desu.edu/admissions/international"]}$q$::jsonb, admission_link = $q$https://www.desu.edu/admissions/international$q$, admission_checked = '2026-11-13' where id = '0df03e08-ee5f-4c49-a358-58391d8817b9' and country = 'United States';
update schools set admission_info = $q${"ug": "First-year: equal of a US high school diploma and a 2.0 GPA. Senior certificate holders (WASSCE and similar) need at least 5 passes at grade C or higher including English, Math and Science. Transfer: 2.0 GPA and evaluations of non-US work.", "english": "TOEFL iBT 79 (4 for tests on or after January 21, 2026), IELTS 6.5, PTE 53, Duolingo 100, or an approved exemption.", "how_to_apply": "Apply online with the fee, English score and transcripts. After approval you get an I-20. F-1 students need 12 credit hours each semester. Health insurance is required. The page lists no scholarships.", "application_fee": "$75, non-refundable.", "documents": "Transcript or course-by-course evaluation (NACES or AICE), English proof.", "fees_link": "https://catalog.twu.edu/undergraduate/admission-information/international-student/", "sources": ["https://catalog.twu.edu/undergraduate/admission-information/international-student/"]}$q$::jsonb, admission_link = $q$https://catalog.twu.edu/undergraduate/admission-information/international-student/$q$, admission_checked = '2026-11-13' where id = '13d3db35-1618-476c-a9c2-2c7f8e57d0c3' and country = 'United States';
update schools set admission_info = $q${"how_to_apply": "International students are automatically considered for merit scholarships when they apply by the deadline. Admission requirements, English minimums and fee were not confirmed on the pages read.", "fees_link": "https://usm.maine.edu/office-international-programs/undergraduate-scholarships/", "sources": ["https://usm.maine.edu/office-international-programs/undergraduate-scholarships/"]}$q$::jsonb, admission_link = $q$https://usm.maine.edu/office-international-programs/undergraduate-scholarships/$q$, admission_checked = '2026-11-13' where id = '579e7b52-9850-46dd-ab99-578a101f4ee8' and country = 'United States';
update schools set admission_info = $q${"ug": "High school transcripts must cover at least 3 years with a 4.0-scale GPA listed. Transfer applicants send transcripts from each college. Non-US college credit needs a WES or ECE evaluation.", "english": "TOEFL iBT 61, IELTS 5.5, PTE Academic 44, iTEP Academic 3.5. Not required with more than 24 US university credit hours.", "how_to_apply": "Apply online, send official transcripts, the International Student Financial Statement and a passport copy. The 2026-2027 cost estimate is $29,537.50 for the first year. Scholarships are in the next entry.", "deadlines": "Fall July 1, Spring November 1.", "application_fee": "$25, non-refundable, no waivers.", "documents": "Official sealed transcripts, financial statement with bank proof dated within 3 months, passport copy.", "fees_link": "https://offices.nsuok.edu/international/UndergraduateAdmission.aspx", "sources": ["https://offices.nsuok.edu/international/UndergraduateAdmission.aspx", "https://scholarships.nsuok.edu/InternationalStudents.aspx"]}$q$::jsonb, admission_link = $q$https://offices.nsuok.edu/international/UndergraduateAdmission.aspx$q$, admission_checked = '2026-11-13' where id = '46325e6a-e053-4280-81ad-b19673be3e6d' and country = 'United States';
update schools set admission_info = $q${"ug": "Educated outside the US: equal of a US high school diploma, official SAT or ACT scores and English proof. Holistic review. Summer entry is not offered to international freshmen.", "pg": "Official transcripts from all schools with mark sheets, English proof, and GRE, GMAT or MAT if the program needs it. Requirements vary by program.", "english": "TOEFL iBT 79 (4 for tests on or after January 21, 2026, confirm with the office), IELTS 6.0, PTE 53, ELS 112, Duolingo 115 (undergraduate and graduate). Scores must be under two years old.", "how_to_apply": "Apply, pay the fee within three days, then send documents. You need bank statements showing at least one year of costs and signed affidavits of support. The pages read did not list scholarships.", "deadlines": "Undergraduate Fall: apply June 1, documents June 15. Spring: October 1, documents October 15. Graduate Fall June 1, Spring December 1, Summer April 1.", "application_fee": "$75, non-refundable (extra $60 for Ed.D.).", "documents": "Transcripts with translations, test scores, bank statements within six months, affidavits of support, passport copy, I-20 or DS-2019 pages if in the US.", "fees_link": "https://inst.uhcl.edu/admissions/apply/international/how-to-apply-international/freshman", "sources": ["https://inst.uhcl.edu/admissions/apply/international/how-to-apply-international/freshman", "https://www.uhcl.edu/admissions/apply/international/how-to-apply-international/graduate"]}$q$::jsonb, admission_link = $q$https://inst.uhcl.edu/admissions/apply/international/how-to-apply-international/freshman$q$, admission_checked = '2026-11-13' where id = '8e5c9b17-4012-404b-aff8-03da709c20dd' and country = 'United States';
update schools set admission_info = $q${"ug": "Send school transcripts (evaluated by WES, IEE or TEC if not from the US), proof of first-year funds within 6 months, and immunization records. US high school graduates also send SAT or ACT.", "pg": "Send evaluated transcripts and proof of funds. Some programs need GRE or GMAT. Dependents need extra funds ($5,000 for a spouse, $3,000 per child).", "english": "Undergraduate: TOEFL iBT 75, IELTS 6.0, Duolingo 95, PTE 50. Graduate: TOEFL iBT 79, IELTS 6.5, Duolingo 105, PTE 56. Many exemptions, including English-medium study with a letter.", "how_to_apply": "Apply, send documents, and show funds. International undergraduates pay NC Promise tuition of $3,500 per semester, with other fees. WCU says graduate students should not expect full scholarships. No named international scholarship was listed.", "deadlines": "Undergraduate: Fall February 1 (freshmen) or April 1 (transfer), Spring October 1. Graduate varies by program.", "documents": "Transcripts, funds certificate and bank letter, immunization records, TB questionnaire.", "fees_link": "https://www.wcu.edu/learn/office-of-global-engagement/international-students/", "sources": ["https://www.wcu.edu/learn/office-of-global-engagement/international-students/"]}$q$::jsonb, admission_link = $q$https://www.wcu.edu/learn/office-of-global-engagement/international-students/$q$, admission_checked = '2026-11-13' where id = '0edb0a76-835d-40d6-b714-1d7057bfe686' and country = 'United States';
update schools set admission_info = $q${"ug": "Apply with the Common App, an essay and the required UMBC questions. UMBC reviews GPA, curriculum, results and essay. SAT or ACT and recommendations are optional.", "english": "Recommended minimums: Duolingo 115, TOEFL 4.5 (80 on the old scale), IELTS 6.5, PTE 53, SAT EBRW 500, or a C in US college English composition.", "how_to_apply": "Apply on the Common App, pay the fee and send official transcripts and English scores. The page lists no scholarships.", "deadlines": "Early Action November 1, Regular Decision December 1 and February 1 (as listed; check the page for fall or spring).", "application_fee": "$75, non-refundable.", "documents": "Official school transcript and leaving exam results, official English test results.", "fees_link": "https://umbc.edu/admissions/undergraduate/international/first-year-international/", "sources": ["https://umbc.edu/admissions/undergraduate/international/first-year-international/"]}$q$::jsonb, admission_link = $q$https://umbc.edu/admissions/undergraduate/international/first-year-international/$q$, admission_checked = '2026-11-13' where id = '3d54af82-d1d0-41d4-9338-4847b55e4309' and country = 'United States';
update schools set admission_info = $q${"ug": "Send academic records from all secondary schools and any diplomas, with notarized English translations, plus exam results such as WAEC or NECO. Admission is rolling.", "english": "TOEFL iBT 79, IELTS 6.0, Duolingo 105, PTE 53, SAT EBRW 500 and others.", "how_to_apply": "Apply and send documents to international@wpunj.edu. After acceptance you take a placement test. The page lists no fee, deadline or scholarships.", "documents": "School records, notarized translations, exam results. Optional: personal statement, CV, recommendations, SAT or ACT.", "fees_link": "https://cms.wpunj.edu/admissions/international/freshman", "sources": ["https://cms.wpunj.edu/admissions/international/freshman"]}$q$::jsonb, admission_link = $q$https://cms.wpunj.edu/admissions/international/freshman$q$, admission_checked = '2026-11-13' where id = 'aacc9e42-01f5-4e89-8f3f-19cee8c7f53a' and country = 'United States';
update schools set admission_info = $q${"ug": "Send transcripts for every secondary school year with English translations. Predicted scores (IB, A-Level or XII board) are strongly recommended. Anyone who is not a US citizen or permanent resident is classed as international.", "pg": "Georgia Tech lists English minimums for graduate applicants. Check your program for GRE or higher scores.", "english": "Undergraduate: proof by an approved University System of Georgia method (minimum score not listed on the page read). Duolingo and an interview are optional extras. Graduate: TOEFL iBT 90 with at least 19 in each section, or IELTS 7.0 overall.", "how_to_apply": "Upload documents through the Document Submission page. The fee, deadlines and financial aid details are on other Georgia Tech pages that were not read.", "fees_link": "https://admission.gatech.edu/international/first-year", "sources": ["https://admission.gatech.edu/international/first-year", "https://catalog.gatech.edu/admissions/grad/english-proficiency-intl-students"]}$q$::jsonb, admission_link = $q$https://admission.gatech.edu/international/first-year$q$, admission_checked = '2026-11-13' where id = '59b9e4ab-5bce-4c32-bb2c-6919b9b4c7a6' and country = 'United States';
update schools set admission_info = $q${"ug": "Official secondary school records and a minimum GPA of 2.5 on a 4.0 scale.", "pg": "Official records from your university and a minimum GPA of 2.75 on a 4.0 scale. GRE, GMAT or MAT is needed only for some programs.", "english": "Undergraduate: TOEFL iBT 61, IELTS 6.0, Duolingo 105 or iTEP Academic Plus 4.5. Scores are valid for two years. Conditional admission and some waivers exist. Graduate score minimums are not listed on the pages checked.", "how_to_apply": "Apply online through MyEIU, then upload the financial affidavit, bank statement and passport copy.", "deadlines": "Fall: May 15. Spring: November 1. Some graduate programs have earlier dates.", "application_fee": "$30 USD, non-refundable.", "documents": "Transcripts or mark sheets with school seal, English translation if needed, English test scores (EIU code 1199), financial affidavit with bank statement, passport copy.", "fees_link": "https://www.eiu.edu/international/undergraduate_checklist.php", "sources": ["https://www.eiu.edu/international/undergraduate_checklist.php", "https://io.eiu.edu/international/ugrequirements.php", "https://booth.eiu.edu/international/graduate_checklist.php", "https://www.eiu.edu/international/international_scholarship.php"]}$q$::jsonb, admission_link = $q$https://www.eiu.edu/international/undergraduate_checklist.php$q$, admission_checked = '2026-11-13' where id = 'cac220bb-c704-4d4c-ab2e-33d8ec99ee9d' and country = 'United States';
update schools set admission_info = $q${"ug": "First-year: official high school transcript in English, usually top 25% of class or about 3.0 GPA. SAT or ACT is optional except for the Honors College and accelerated programs.", "pg": "Master's: GPA of about 3.0 recommended, resume and one recommendation letter recommended. PhD: GPA 3.5, statement of purpose, resume and three recommendation letters. GRE or GMAT is optional for most master's programs and required for some PhD programs.", "english": "Undergraduate: TOEFL iBT 79 (or 4.0 new scale), IELTS 6.0, Duolingo 100 or PTE 53. Graduate: TOEFL iBT 79 (or 4.0), IELTS 6.5, Duolingo 120 or PTE 57. Scores are valid for two years.", "how_to_apply": "First-year students apply through the Common App. Transfer and graduate students apply on the NJIT website.", "deadlines": "Graduate master's: May 1 for Fall and November 15 for Spring. PhD: December 15 for Fall and October 15 for Spring. Undergraduate dates are on the NJIT key dates page.", "application_fee": "$75 USD, non-refundable. Graduate applicants can get a fee waiver code by attending an international information session.", "documents": "Transcripts from all schools attended, English test score, SAT or ACT where used (NJIT code 2513 or 2580 for ACT), portfolio for architecture and design. Graduate admission can be decided on unofficial documents, but official ones are needed to enroll.", "fees_link": "https://www.njit.edu/admissions/how-apply-international-students", "sources": ["https://www.njit.edu/admissions/how-apply-international-students", "https://www.njit.edu/graduate-international-admissions-process"]}$q$::jsonb, admission_link = $q$https://www.njit.edu/admissions/how-apply-international-students$q$, admission_checked = '2026-11-13' where id = '02f0d4cf-ff52-4629-a76b-855de728d0cb' and country = 'United States';
update schools set admission_info = $q${"ug": "Finished secondary school with a US-equivalent GPA of 2.6 or higher, or ACT 21 or SAT 1070, plus English proof.", "pg": "Degree equivalent to a US bachelor's from a recognized institution. Some programs need test scores, recommendation letters, a statement of purpose and a resume.", "english": "Undergraduate: TOEFL iBT 71, IELTS 6.0, Duolingo 105 or PTE 48. Graduate: TOEFL iBT 79, IELTS 6.0, Duolingo 110 or PTE 53. Some degrees and WAEC results from English-medium schools may qualify.", "how_to_apply": "Apply online or through the Common App (undergraduate) or the USD portal or GradCAS (graduate). Send documents by email or mail.", "deadlines": "Undergraduate: Spring December 15, Fall August 1. Graduate: Fall July 15 to August 1 depending on program, Spring December 5 for some programs. Scholarship consideration dates are June 1 (Fall) and October 1 (Spring).", "application_fee": "Graduate: $38 USD, non-refundable. Undergraduate fee amount is not stated on the page checked.", "documents": "Transcripts (official ones due 30 days before classes), English proof, passport copy, statement of finances for the I-20. Graduate: also recommendation letters, statement of purpose and resume.", "fees_link": "https://www.usd.edu/Admissions-and-Aid/International-Admissions/Applying-for-International-Undergraduate-Admission", "sources": ["https://www.usd.edu/Admissions-and-Aid/International-Admissions/Applying-for-International-Undergraduate-Admission", "https://www.usd.edu/Admissions-and-Aid/International-Admissions/Applying-for-International-Graduate-Admission", "https://usd.edu/international-office/international-scholarships"]}$q$::jsonb, admission_link = $q$https://www.usd.edu/Admissions-and-Aid/International-Admissions/Applying-for-International-Undergraduate-Admission$q$, admission_checked = '2026-11-13' where id = '5cadacd8-a695-4ab8-af3d-6bce4267183d' and country = 'United States';
