update schools set admission_info = $q${"ug": "Not a US citizen or permanent resident. Secondary credentials evaluated by ECE, WES or OneEarthEvaluation with a GPA. Passport page and proof of funds (about $34,276 for 2026-2027).", "pg": "Undergraduate degree required for master's or PhD. Estimated cost for 2026-2027 is about $39,408.", "english": "Undergraduate: TOEFL iBT 71, IELTS 6.0, Duolingo 110, PTE 48 or SAT reading and writing 430. Graduate: TOEFL iBT 79 or IELTS 6.0. Scores within 24 months.", "how_to_apply": "Apply online through the Universities of Wisconsin application and send documents first.", "deadlines": "Recommended: July 1 for Fall and December 1 for Spring. Freshman scholarship cutoffs: July 1 (Excellence) and July 15 (Merit and Distinction) for Fall.", "application_fee": "$50 listed on the Rock County campus page. Whitewater pages did not state a fee.", "documents": "Evaluated credentials, passport page, financial proof for the I-20, English test.", "fees_link": "https://www.uww.edu/global-education/international-admissions", "sources": ["https://www.uww.edu/global-education/international-admissions"]}$q$::jsonb, admission_link = $q$https://www.uww.edu/global-education/international-admissions$q$, admission_checked = '2026-11-13' where id = '5b9b67df-faf2-464c-89fa-7da833c0bbc2' and country = 'United States';
update schools set admission_info = $q${"ug": "Secondary transcripts, proof of graduation, financial statement form with original funds proof, passport copy and English score. Music, theatre, dance and visual arts need an audition or portfolio.", "pg": "Online application, transcripts (evaluated if not in English or not on a 4.0 scale), resume, statement of intent and recommendations. GRE only for some programs. You need at least $38,500 in liquid funds for the I-20.", "english": "Undergraduate: IELTS 6.0, Duolingo 105, PTE 53, SAT reading 480 or C1 Advanced 176. TOEFL iBT 79 for tests before January 21, 2026 (the new-scale figure on the page looks wrong, confirm with admissions). Graduate: TOEFL iBT 79, IELTS 6.5 or Duolingo 105. Code 2539.", "how_to_apply": "Apply through Common App or the SUNY application. Graduate students apply online.", "deadlines": "Undergraduate and graduate deadlines are not listed on the pages checked.", "application_fee": "Undergraduate: $50 on the Common App. Graduate: $75.", "documents": "Transcripts, financial statement with bank proof, passport copy, English score, audition or portfolio where needed.", "fees_link": "https://www.fredonia.edu/admissions-aid/international", "sources": ["https://www.fredonia.edu/admissions-aid/international", "https://www.fredonia.edu/academics/graduate-studies/international-graduate-applicant-requirements"]}$q$::jsonb, admission_link = $q$https://www.fredonia.edu/admissions-aid/international$q$, admission_checked = '2026-11-13' where id = '86168bd7-6bb7-499d-85c0-9cd0026e73a5' and country = 'United States';
